-- 把既有的「Mandarin A1 Course (Kolecion)」課程單元換成新版內容（菲律賓移工版，20 個單元、240 小時）。
-- 依「單元位置」（1～20）更新名稱、時數、學習重點、詞彙、例句、對話與分類：單元 ID 不變，工人的學習進度與測驗紀錄都保留。
-- ⚠️ 會覆蓋你在網站上對這些單元做過的修改；位置不在 1～20 的單元不會被動到；缺少的位置會補上新單元。
-- 這個檔案由 scripts/build-mandarin-a1-course.mjs 產生，請改 scripts/mandarin-a1/*.mjs 再重新產生。
--
-- 用法（在專案資料夾，center_email 換成訓練中心會員的 Email；先備份：npm run db:backup）：
--   docker cp scripts/update-mandarin-a1-course.sql tk_saas_sales_demo-postgres-1:/tmp/update-a1.sql
--   docker exec -e PGCLIENTENCODING=UTF8 tk_saas_sales_demo-postgres-1 psql -U postgres -d kolecion_db -v center_email=center@example.com -f /tmp/update-a1.sql
\set ON_ERROR_STOP on

-- 找不到訓練中心就中止，不寫入任何資料。
SELECT COALESCE(max(id), 0) AS center_id FROM hr_members
WHERE role = 'training_center' AND lower(email) = lower(:'center_email') \gset
SELECT :center_id = 0 AS missing_center \gset
\if :missing_center
  \echo '找不到這個 Email 的訓練中心會員（會員類型必須是訓練中心），已中止。'
  \quit
\endif

-- 只看課程名稱，不看證照名稱：證照在網站上改過名（例如「中文A1」改成「Mandarin A1」）也找得到。
-- 同名課程不只一個時，選單元最多的那個（一樣多就選最早建立的）。
SELECT COALESCE((SELECT co.id FROM hr_tc_courses co
  WHERE co.center_id = :center_id AND co.name = 'Mandarin A1 Course (Kolecion)'
  ORDER BY (SELECT count(*) FROM hr_tc_course_units u WHERE u.course_id = co.id) DESC, co.id
  LIMIT 1), 0) AS course_id \gset
SELECT :course_id = 0 AS missing_course \gset
\if :missing_course
  \echo '找不到 Mandarin A1 Course (Kolecion) 課程，請先執行 seed-mandarin-a1-course.sql，已中止。'
  \quit
\endif

BEGIN;

ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS vocabulary TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS dialogue TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS category TEXT NOT NULL DEFAULT '';
ALTER TABLE hr_tc_course_units ADD COLUMN IF NOT EXISTS category_en TEXT NOT NULL DEFAULT '';

CREATE TEMP TABLE a1_units(position INTEGER, name TEXT, name_en TEXT, hours INTEGER, topics TEXT, topics_en TEXT, examples TEXT, vocabulary TEXT, dialogue TEXT, category TEXT, category_en TEXT) ON COMMIT DROP;
INSERT INTO a1_units(position, name, name_en, hours, topics, topics_en, examples, vocabulary, dialogue, category, category_en) VALUES
    (1, E'發音與聲調', E'Pronunciation & Tones', 10, E'目標：分辨四個聲調與輕聲、看懂拼音、會說課堂用語。發音：一聲高而平，二聲往上揚，三聲先降再升，四聲快速往下，輕聲短而輕（的、嗎、了不標聲調）。變調：兩個三聲相連，前一個唸二聲，拼音照標原調（你好 nǐ hǎo 唸 ní hǎo）；「不」在四聲前唸 bú（不是 bú shì），其他唸 bù；「一」在四聲前唸 yí（一次 yí cì），在一、二、三聲前唸 yì（一天 yì tiān），單唸、數數、序數唸 yī（第一 dì-yī）。拼寫：j、q、x、y 後面的 ü 寫成 u（去 qù），n、l 後面寫 ü（女 nǚ、綠 lǜ）；a、o、e 開頭的音節接在後面要加隔音符號（晚安 wǎn''ān）。zh、ch、sh、r 要捲舌，z、c、s 不捲舌。文化：在台灣上課先說「老師好」，聽不懂就說「請再說一次」，不必不好意思。', E'Goals: hear the four tones and the neutral tone, read pinyin, use classroom phrases. Tones: 1st high and level, 2nd rising, 3rd dipping, 4th falling fast; the neutral tone is short and light and has no mark (的 de, 嗎 ma, 了 le). Tone changes: two 3rd tones together, the first is said as a 2nd tone but still written as 3rd (nǐ hǎo is said ní hǎo); 不 is bú before a 4th tone (bú shì), otherwise bù; 一 is yí before a 4th tone (yí cì), yì before 1st, 2nd and 3rd tones (yì tiān), and yī alone, in counting and ordinals (dì-yī). Spelling: after j, q, x, y the ü is written u (qù); after n and l write ü (nǚ, lǜ); put an apostrophe before a syllable starting with a, o or e (wǎn''ān). Curl the tongue for zh, ch, sh, r but not for z, c, s. Culture: greet the teacher with 老師好 (Lǎoshī hǎo) and say 請再說一次 (Qǐng zài shuō yí cì) when you do not understand.', E'你好。 | Nǐ hǎo. | Hello. (3rd + 3rd tone: say ní hǎo)\n我很好。 | Wǒ hěn hǎo. | I am fine. (say wó hén hǎo)\n不是。 | Bú shì. | No, it is not. (不 becomes bú before a 4th tone)\n請再說一次。 | Qǐng zài shuō yí cì. | Please say it again. (一 becomes yí before a 4th tone)\n請說慢一點。 | Qǐng shuō màn yìdiǎn. | Please speak a little slower. (一 becomes yì before a 3rd tone)', E'媽 | mā | mother (1st tone)\n麻 | má | hemp (2nd tone)\n馬 | mǎ | horse (3rd tone)\n罵 | mà | to scold (4th tone)\n嗎 | ma | question particle (neutral tone)\n湯 | tāng | soup\n糖 | táng | sugar\n躺 | tǎng | to lie down\n燙 | tàng | very hot to the touch\n書 | shū | book\n熟 | shú | cooked\n水 | shuǐ | water\n睡 | shuì | to sleep\n你 | nǐ | you\n好 | hǎo | good\n我 | wǒ | I; me\n他 | tā | he; him\n她 | tā | she; her\n是 | shì | to be; yes\n不 | bù | not; no\n女 | nǚ | female\n綠 | lǜ | green\n去 | qù | to go\n魚 | yú | fish\n雨 | yǔ | rain\n吃 | chī | to eat\n喝 | hē | to drink\n請 | qǐng | please\n請問 | qǐngwèn | excuse me, may I ask\n懂 | dǒng | to understand\n聽 | tīng | to listen\n說 | shuō | to speak; to say\n再 | zài | again\n慢 | màn | slow\n老師 | lǎoshī | teacher\n同學 | tóngxué | classmate', E'A：老師好！ | Lǎoshī hǎo! | Hello, teacher!\nB：同學好！請聽。 | Tóngxué hǎo! Qǐng tīng. | Hello, class! Please listen.\nA：老師，對不起，我聽不懂。 | Lǎoshī, duìbuqǐ, wǒ tīng bù dǒng. | Teacher, sorry, I do not understand.\nB：沒問題。我說慢一點。 | Méi wèntí. Wǒ shuō màn yìdiǎn. | No problem. I will speak more slowly.\nA：請再說一次。 | Qǐng zài shuō yí cì. | Please say it again.\nB：媽、麻、馬、罵。 | Mā, má, mǎ, mà. | mā, má, mǎ, mà: the four tones.\nA：媽、麻、馬、罵。 | Mā, má, mǎ, mà. | mā, má, mǎ, mà (repeating).\nB：很好！ | Hěn hǎo! | Very good!\nA：謝謝老師！ | Xièxie lǎoshī! | Thank you, teacher!\nB：不客氣。 | Bú kèqì. | You are welcome.', E'基礎', E'Basics'),
    (2, E'問候、禮貌與自我介紹', E'Greetings, Politeness & Introductions', 10, E'目標：會打招呼、道謝與道歉；會說自己的名字、國籍和工作；會稱呼雇主家人。句型：我是＋國籍／工作（我是菲律賓人）、我叫＋名字、你叫什麼名字？、……呢？。發音：「不客氣」的「不」在四聲前唸 bú；「不好意思」的「不」在三聲前唸 bù；「早安」「晚安」要寫隔音符號 zǎo''ān、wǎn''ān。台灣讀音：「誰」多唸 shéi。文化：台灣人見面不一定握手，點頭微笑就很有禮貌；麻煩別人或要開口問問題時，先說「不好意思」；稱呼長輩用「阿公」「阿嬤」，稱呼雇主用「先生」「太太」「老闆」。', E'Goals: greet people, say thank you and sorry, say your name, nationality and job, and address your employer''s family. Patterns: 我是 (wǒ shì) + nationality or job (我是菲律賓人 Wǒ shì Fēilǜbīnrén), 我叫 (wǒ jiào) + name, 你叫什麼名字？ (Nǐ jiào shénme míngzi?), ……呢？ (… ne?). Pronunciation: 不 (bù) in 不客氣 is bú before a 4th tone; 不 (bù) in 不好意思 is bù before a 3rd tone; write the apostrophe in zǎo''ān and wǎn''ān. Taiwan reading: 誰 (shéi) is usually shéi. Culture: people in Taiwan often nod and smile instead of shaking hands; say 不好意思 (bù hǎoyìsi) before you ask for help or a favor; call older people 阿公 (āgōng) and 阿嬤 (āmà), and your employer 先生 (xiānshēng), 太太 (tàitai) or 老闆 (lǎobǎn).', E'我是菲律賓人。 | Wǒ shì Fēilǜbīnrén. | I am Filipino.\n我叫安娜。 | Wǒ jiào Ānnà. | My name is Anna.\n我不是台灣人。 | Wǒ bú shì Táiwānrén. | I am not Taiwanese.\n你叫什麼名字？ | Nǐ jiào shénme míngzi? | What is your name?\n我是看護，她是幫傭。 | Wǒ shì kānhù, tā shì bāngyōng. | I am a caregiver, she is a domestic helper.', E'你好 | nǐ hǎo | hello\n您好 | nín hǎo | hello (polite)\n早安 | zǎo''ān | good morning\n午安 | wǔ''ān | good afternoon\n晚安 | wǎn''ān | good night\n歡迎 | huānyíng | welcome\n謝謝 | xièxie | thank you\n不客氣 | bú kèqì | you are welcome\n對不起 | duìbuqǐ | sorry\n沒關係 | méi guānxì | it is okay\n不好意思 | bù hǎoyìsi | excuse me (sorry to bother you)\n再見 | zàijiàn | goodbye\n明天見 | míngtiān jiàn | see you tomorrow\n名字 | míngzi | name\n姓 | xìng | surname; to be surnamed\n貴姓 | guìxìng | your surname (polite)\n叫 | jiào | to be called\n什麼 | shénme | what\n誰 | shéi | who\n哪 | nǎ | which\n國家 | guójiā | country\n菲律賓 | Fēilǜbīn | the Philippines\n台灣 | Táiwān | Taiwan\n印尼 | Yìnní | Indonesia\n越南 | Yuènán | Vietnam\n泰國 | Tàiguó | Thailand\n人 | rén | person\n菲律賓人 | Fēilǜbīnrén | Filipino (person)\n台灣人 | Táiwānrén | Taiwanese (person)\n朋友 | péngyǒu | friend\n工作 | gōngzuò | job; to work\n移工 | yígōng | migrant worker\n看護 | kānhù | caregiver\n幫傭 | bāngyōng | domestic helper\n作業員 | zuòyèyuán | factory operator\n農工 | nónggōng | farm worker\n先生 | xiānshēng | Mr.; sir; husband\n小姐 | xiǎojiě | Miss; Ms.\n太太 | tàitai | Mrs.; madam\n阿公 | āgōng | grandpa\n阿嬤 | āmà | grandma\n老闆 | lǎobǎn | boss\n雇主 | gùzhǔ | employer\n很 | hěn | very\n高興 | gāoxìng | happy; glad\n認識 | rènshì | to get to know (a person)\n也 | yě | also; too\n呢 | ne | and you? (question particle)\n歲 | suì | years old\n我們 | wǒmen | we; us\n你們 | nǐmen | you (plural)\n他們 | tāmen | they; them', E'A：您好！我叫安娜，我是菲律賓人。 | Nín hǎo! Wǒ jiào Ānnà, wǒ shì Fēilǜbīnrén. | Hello! My name is Anna. I am Filipino.\nB：你好！歡迎你來台灣。 | Nǐ hǎo! Huānyíng nǐ lái Táiwān. | Hello! Welcome to Taiwan.\nA：謝謝！請問您貴姓？ | Xièxie! Qǐngwèn nín guìxìng? | Thank you! May I ask your surname?\nB：我姓陳。你叫我陳太太。 | Wǒ xìng Chén. Nǐ jiào wǒ Chén tàitai. | My surname is Chen. Call me Mrs. Chen.\nA：陳太太好！很高興認識您。 | Chén tàitai hǎo! Hěn gāoxìng rènshì nín. | Hello, Mrs. Chen! Nice to meet you.\nB：我也很高興認識你。這是阿嬤。 | Wǒ yě hěn gāoxìng rènshì nǐ. Zhè shì āmà. | Nice to meet you too. This is Grandma.\nA：阿嬤好！我是您的看護。 | Āmà hǎo! Wǒ shì nín de kānhù. | Hello, Grandma! I am your caregiver.\nB：好，好。你幾歲？ | Hǎo, hǎo. Nǐ jǐ suì? | Good, good. How old are you?\nA：我三十歲。 | Wǒ sānshí suì. | I am thirty years old.', E'基礎', E'Basics'),
    (3, E'數字、時間與日期', E'Numbers, Time & Dates', 12, E'目標：會說 0 到 10000 的數字和電話號碼；會問時間、星期和日期；會約時間。句型：現在幾點？、今天星期幾？、……是多少？、幾月幾號。發音：「一」數數和唸號碼時唸 yī（一一九 yī yī jiǔ），在量詞前要變調（一個 yí ge、一天 yì tiān）；「十二」要寫隔音符號 shí''èr；「兩」用在量詞前（兩個人），「二」用在數數和號碼。台灣讀音：「星期」台灣唸 xīngqí，口語也常說「禮拜」lǐbài；「多少」台灣唸 duōshǎo。文化：台灣手機號碼是 09 開頭的十位數；約時間要準時，晚到要先打電話說「不好意思，我會晚一點到」。', E'Goals: say numbers from 0 to 10,000 and phone numbers, ask the time, the day and the date, and agree on a time. Patterns: 現在幾點？ (Xiànzài jǐ diǎn?), 今天星期幾？ (Jīntiān xīngqí jǐ?), ……是多少？ (… shì duōshǎo?), 幾月幾號 (jǐ yuè jǐ hào). Pronunciation: 一 is yī when counting or reading numbers (一一九 yī yī jiǔ) but changes before measure words (一個 yí ge, 一天 yì tiān); write the apostrophe in shí''èr; use 兩 (liǎng) before measure words (兩個人 liǎng ge rén) and 二 (èr) for counting and numbers. Taiwan readings: 星期 is xīngqí, and people also say 禮拜 lǐbài; 多少 is duōshǎo. Culture: Taiwan mobile numbers have ten digits and start with 09; be on time, and call ahead if you will be late.', E'現在幾點？ | Xiànzài jǐ diǎn? | What time is it now?\n現在下午三點半。 | Xiànzài xiàwǔ sān diǎn bàn. | It is half past three in the afternoon.\n今天星期五。 | Jīntiān xīngqíwǔ. | Today is Friday.\n我的電話號碼是零九一二，三四五，六七八。 | Wǒ de diànhuà hàomǎ shì líng jiǔ yī èr, sān sì wǔ, liù qī bā. | My phone number is 0912-345-678.\n我十月一號來台灣。 | Wǒ shí yuè yī hào lái Táiwān. | I come to Taiwan on October 1st.', E'零 | líng | zero\n一 | yī | one\n二 | èr | two\n三 | sān | three\n四 | sì | four\n五 | wǔ | five\n六 | liù | six\n七 | qī | seven\n八 | bā | eight\n九 | jiǔ | nine\n十 | shí | ten\n百 | bǎi | hundred\n千 | qiān | thousand\n萬 | wàn | ten thousand\n兩 | liǎng | two (before measure words)\n幾 | jǐ | how many (small number)\n多少 | duōshǎo | how many; how much\n號碼 | hàomǎ | number\n電話 | diànhuà | telephone\n點 | diǎn | o''clock\n分 | fēn | minute (on the clock)\n半 | bàn | half\n現在 | xiànzài | now\n時間 | shíjiān | time\n小時 | xiǎoshí | hour\n幾點 | jǐ diǎn | what time\n今天 | jīntiān | today\n明天 | míngtiān | tomorrow\n昨天 | zuótiān | yesterday\n每天 | měitiān | every day\n星期 | xīngqí | week\n禮拜 | lǐbài | week (spoken)\n星期一 | xīngqíyī | Monday\n星期天 | xīngqítiān | Sunday\n週末 | zhōumò | weekend\n月 | yuè | month\n號 | hào | day of the month\n年 | nián | year\n今年 | jīnnián | this year\n上個月 | shàng ge yuè | last month\n下個月 | xià ge yuè | next month\n生日 | shēngrì | birthday\n早上 | zǎoshàng | early morning\n上午 | shàngwǔ | morning (before noon)\n中午 | zhōngwǔ | noon\n下午 | xiàwǔ | afternoon\n晚上 | wǎnshàng | evening\n什麼時候 | shénme shíhòu | when\n第 | dì | ordinal prefix (first, second)', E'A：請問，現在幾點？ | Qǐngwèn, xiànzài jǐ diǎn? | Excuse me, what time is it now?\nB：現在早上八點十分。 | Xiànzài zǎoshàng bā diǎn shí fēn. | It is ten past eight in the morning.\nA：謝謝。今天星期幾？ | Xièxie. Jīntiān xīngqí jǐ? | Thanks. What day is today?\nB：今天星期六。明天星期天，你休息。 | Jīntiān xīngqíliù. Míngtiān xīngqítiān, nǐ xiūxí. | Today is Saturday. Tomorrow is Sunday, your day off.\nA：太好了！我想打電話給我媽媽。 | Tài hǎo le! Wǒ xiǎng dǎ diànhuà gěi wǒ māma. | Great! I want to call my mother.\nB：你媽媽的電話號碼是多少？ | Nǐ māma de diànhuà hàomǎ shì duōshǎo? | What is your mother''s phone number?\nA：是零九一七，二三四，五六七八。 | Shì líng jiǔ yī qī, èr sān sì, wǔ liù qī bā. | It is 0917-234-5678.\nB：你幾點打？ | Nǐ jǐ diǎn dǎ? | What time will you call?\nA：晚上七點半。 | Wǎnshàng qī diǎn bàn. | At half past seven in the evening.', E'基礎', E'Basics'),
    (4, E'機場、仲介與證件', E'Airport, Broker & Documents', 10, E'目標：在機場找到仲介；會說自己的證件；證件不見時會求助。句型：這是我的＋證件、我的……不見了、請在這裡簽名、我要找＋人。發音：「護照」hùzhào、「居留證」jūliúzhèng 的 j 後面寫 u 其實唸 ü；「不見了」的「不」在四聲前唸 bú。文化：在台灣，護照和居留證要自己保管，依法雇主和仲介不可以扣留你的證件；簽名以前看不懂可以請翻譯說明，不懂就不要簽；仲介的電話號碼要存在手機裡。', E'Goals: find your broker at the airport, talk about your documents, and ask for help when a document is lost. Patterns: 這是我的 (zhè shì wǒ de) + document, 我的……不見了 (wǒ de … bújiàn le), 請在這裡簽名 (Qǐng zài zhèlǐ qiānmíng), 我要找 (wǒ yào zhǎo) + person. Pronunciation: in jūliúzhèng the u after j is said like ü; 不 (bù) in 不見了 is bú before a 4th tone. Culture: in Taiwan you keep your own passport and residence permit (ARC); by law your employer and broker may not hold your documents. Before you sign, ask an interpreter to explain anything you do not understand, and do not sign if you still do not understand. Save your broker''s phone number in your phone.', E'這是我的護照。 | Zhè shì wǒ de hùzhào. | This is my passport.\n我的居留證不見了。 | Wǒ de jūliúzhèng bú jiàn le. | My residence permit is missing.\n請在這裡簽名。 | Qǐng zài zhèlǐ qiānmíng. | Please sign here.\n我要找我的仲介。 | Wǒ yào zhǎo wǒ de zhòngjiè. | I am looking for my broker.\n護照要自己保管。 | Hùzhào yào zìjǐ bǎoguǎn. | Keep your passport yourself.', E'機場 | jīchǎng | airport\n飛機 | fēijī | airplane\n護照 | hùzhào | passport\n居留證 | jūliúzhèng | residence permit (ARC)\n簽證 | qiānzhèng | visa\n證件 | zhèngjiàn | ID documents\n合約 | héyuē | contract\n仲介 | zhòngjiè | broker; recruitment agent\n公司 | gōngsī | company\n翻譯 | fānyì | interpreter; to translate\n行李 | xínglǐ | luggage\n箱子 | xiāngzi | suitcase; box\n地址 | dìzhǐ | address\n宿舍 | sùshè | dormitory\n照片 | zhàopiàn | photo\n體檢 | tǐjiǎn | health checkup\n指紋 | zhǐwén | fingerprint\n簽名 | qiānmíng | to sign; signature\n填 | tián | to fill in\n表格 | biǎogé | form\n影印 | yǐngyìn | to photocopy\n等 | děng | to wait\n排隊 | páiduì | to line up\n帶 | dài | to bring\n給 | gěi | to give\n拿 | ná | to take; to hold\n找 | zhǎo | to look for\n在 | zài | to be at; at\n這 | zhè | this\n那 | nà | that\n有 | yǒu | to have; there is\n沒有 | méiyǒu | not have; there is not\n的 | de | possessive particle (''s)\n不見了 | bú jiàn le | missing; lost\n幫忙 | bāngmáng | to help\n問題 | wèntí | question; problem\n知道 | zhīdào | to know (a fact)\n可以 | kěyǐ | can; may\n要 | yào | to want; to need\n來 | lái | to come\n到 | dào | to arrive\n接 | jiē | to pick up (a person)\n住 | zhù | to live; to stay\n新 | xīn | new\n第一次 | dì-yī cì | the first time\n外國人 | wàiguórén | foreigner\n保管 | bǎoguǎn | to keep safe\n自己 | zìjǐ | oneself\n聯絡 | liánluò | to contact', E'A：你好，你是安娜嗎？我是仲介公司的李先生。 | Nǐ hǎo, nǐ shì Ānnà ma? Wǒ shì zhòngjiè gōngsī de Lǐ xiānshēng. | Hello, are you Anna? I am Mr. Li from the broker agency.\nB：是，我是安娜。李先生好！ | Shì, wǒ shì Ānnà. Lǐ xiānshēng hǎo! | Yes, I am Anna. Hello, Mr. Li!\nA：歡迎來台灣！你的護照呢？ | Huānyíng lái Táiwān! Nǐ de hùzhào ne? | Welcome to Taiwan! Where is your passport?\nB：在這裡。 | Zài zhèlǐ. | It is here.\nA：好。我們先去體檢，再去宿舍。 | Hǎo. Wǒmen xiān qù tǐjiǎn, zài qù sùshè. | Okay. First we go for the health checkup, then to the dormitory.\nB：請問，宿舍的地址是什麼？ | Qǐngwèn, sùshè de dìzhǐ shì shénme? | Excuse me, what is the dormitory address?\nA：我等一下給你。有問題就打電話給我。 | Wǒ děng yíxià gěi nǐ. Yǒu wèntí jiù dǎ diànhuà gěi wǒ. | I will give it to you in a moment. Call me if you have a problem.\nB：好，謝謝李先生！ | Hǎo, xièxie Lǐ xiānshēng! | Okay, thank you, Mr. Li!', E'到台灣生活', E'Living in Taiwan'),
    (5, E'住宿與垃圾分類', E'Housing & Sorting Trash', 12, E'目標：會說房間和宿舍裡的東西；會報告東西壞了；會照台灣的方式分類垃圾、遵守宿舍規定。句型：……在哪裡？、……壞了、……要＋動作（寶特瓶要資源回收）、不可以＋動作。發音：「垃圾」台灣標準讀音 lèsè，口語也常聽到 lājī，兩種都要聽得懂；「冷氣」lěngqì 的 q 像「ch」但嘴角往兩邊拉。文化：台灣「垃圾不落地」，要在固定時間把垃圾拿給垃圾車，聽到垃圾車的音樂就要出門；一般垃圾、資源回收、廚餘要分開；宿舍晚上要安靜，室內不可以抽菸。', E'Goals: name things in your room and dormitory, report that something is broken, sort trash the Taiwan way, and follow dorm rules. Patterns: ……在哪裡？ (… zài nǎlǐ?), ……壞了 (… huài le), …… + 要 (yào) + action (寶特瓶要資源回收 Bǎotèpíng yào zīyuán huíshōu), 不可以 (bù kěyǐ) + action. Pronunciation: 垃圾 is lèsè in standard Taiwan Mandarin, but you will also hear lājī, so learn both; the q in lěngqì is like "ch" with the lips spread. Culture: in Taiwan trash never sits on the street. You hand it to the garbage truck at fixed times, so go out when you hear its music. Keep general trash, recycling and food scraps apart. Keep quiet at night and do not smoke indoors.', E'垃圾車晚上七點來。 | Lèsèchē wǎnshàng qī diǎn lái. | The garbage truck comes at seven in the evening.\n寶特瓶要資源回收。 | Bǎotèpíng yào zīyuán huíshōu. | Plastic bottles go to recycling.\n房間的冷氣壞了。 | Fángjiān de lěngqì huài le. | The air conditioner in the room is broken.\n宿舍裡不可以抽菸。 | Sùshè lǐ bù kěyǐ chōuyān. | No smoking in the dormitory.\n請關燈。 | Qǐng guān dēng. | Please turn off the light.', E'房間 | fángjiān | room\n床 | chuáng | bed\n棉被 | miánbèi | blanket; quilt\n枕頭 | zhěntou | pillow\n桌子 | zhuōzi | table\n椅子 | yǐzi | chair\n衣櫃 | yīguì | wardrobe\n廁所 | cèsuǒ | toilet; restroom\n浴室 | yùshì | bathroom\n廚房 | chúfáng | kitchen\n冰箱 | bīngxiāng | refrigerator\n洗衣機 | xǐyījī | washing machine\n冷氣 | lěngqì | air conditioner\n電風扇 | diànfēngshàn | electric fan\n燈 | dēng | light; lamp\n開 | kāi | to turn on; to open\n關 | guān | to turn off; to close\n門 | mén | door\n窗戶 | chuānghù | window\n鑰匙 | yàoshi | key\n熱水 | rèshuǐ | hot water\n插座 | chāzuò | power outlet\n壞了 | huài le | broken\n修 | xiū | to repair\n室友 | shìyǒu | roommate\n垃圾 | lèsè | trash\n垃圾車 | lèsèchē | garbage truck\n垃圾袋 | lèsèdài | garbage bag\n資源回收 | zīyuán huíshōu | recycling\n廚餘 | chúyú | food scraps\n寶特瓶 | bǎotèpíng | plastic bottle\n紙類 | zhǐlèi | paper (for recycling)\n鐵罐 | tiěguàn | tin can\n分類 | fēnlèi | to sort\n丟 | diū | to throw away\n倒垃圾 | dào lèsè | to take out the trash\n安靜 | ānjìng | quiet\n吵 | chǎo | noisy\n乾淨 | gānjìng | clean\n髒 | zāng | dirty\n規定 | guīdìng | rule\n不可以 | bù kěyǐ | not allowed\n抽菸 | chōuyān | to smoke\n洗澡 | xǐzǎo | to take a bath\n桶子 | tǒngzi | bucket; bin', E'A：安娜，這是你的房間。 | Ānnà, zhè shì nǐ de fángjiān. | Anna, this is your room.\nB：謝謝！請問，廁所在哪裡？ | Xièxie! Qǐngwèn, cèsuǒ zài nǎlǐ? | Thank you! Excuse me, where is the toilet?\nA：在那裡。洗衣機在外面。 | Zài nàlǐ. Xǐyījī zài wàimiàn. | Over there. The washing machine is outside.\nB：垃圾要怎麼丟？ | Lèsè yào zěnme diū? | How do I throw away trash?\nA：要分類。紙類、寶特瓶、鐵罐是資源回收。 | Yào fēnlèi. Zhǐlèi, bǎotèpíng, tiěguàn shì zīyuán huíshōu. | You must sort it. Paper, plastic bottles and cans are recycling.\nB：廚餘呢？ | Chúyú ne? | What about food scraps?\nA：廚餘放這個桶子。垃圾車晚上七點來。 | Chúyú fàng zhège tǒngzi. Lèsèchē wǎnshàng qī diǎn lái. | Put food scraps in this bin. The garbage truck comes at seven in the evening.\nB：好，我知道了。 | Hǎo, wǒ zhīdào le. | Okay, I understand.\nA：還有，晚上十點以後要安靜。 | Háiyǒu, wǎnshàng shí diǎn yǐhòu yào ānjìng. | Also, be quiet after ten at night.\nB：好的，沒問題。 | Hǎo de, méi wèntí. | Sure, no problem.', E'到台灣生活', E'Living in Taiwan'),
    (6, E'吃飯與便利商店', E'Meals & Convenience Stores', 12, E'目標：會在便利商店和小吃店點餐、說出不吃的東西；會說內用或外帶、要不要加熱。句型：我要＋數量＋量詞＋東西（我要一個便當）、……還是……？、我不吃＋東西、請幫我＋動作。發音：「一個」唸 yí ge（「個」輕聲，前面的「一」照四聲變調）；「一杯」唸 yì bēi；「不辣」唸 bú là。台灣讀音：「微波」台灣唸 wéibō。文化：台灣便利商店很多，可以買便當、繳費、儲值；店員會問「要微波嗎？」「要袋子嗎？」，塑膠袋要另外付錢；不吃豬肉或吃素可以直接說「我不吃豬肉」「我吃素」。', E'Goals: order at convenience stores and small eateries, say what you do not eat, and say whether to eat in or take out and whether to heat food. Patterns: 我要 (wǒ yào) + number + measure word + thing (我要一個便當 wǒ yào yí ge biàndāng), ……還是……？ (… háishì …?), 我不吃 (wǒ bù chī) + food, 請幫我 (qǐng bāng wǒ) + action. Pronunciation: 一個 is yí ge (個 ge is neutral, and 一 yī changes as before a 4th tone); 一杯 is yì bēi; 不辣 is bú là. Taiwan reading: 微波 is wéibō. Culture: convenience stores are everywhere in Taiwan. You can buy meals, pay bills and top up cards there. Clerks ask 要微波嗎？ (Yào wéibō ma?) (heat it up?) and 要袋子嗎？ (Yào dàizi ma?) (need a bag?), and plastic bags cost extra. If you do not eat pork or you are vegetarian, just say 我不吃豬肉 (Wǒ bù chī zhūròu) or 我吃素 (wǒ chīsù).', E'我要一個雞肉便當。 | Wǒ yào yí ge jīròu biàndāng. | I want one chicken lunch box.\n請幫我微波。 | Qǐng bāng wǒ wéibō. | Please heat it in the microwave for me.\n我不吃豬肉。 | Wǒ bù chī zhūròu. | I do not eat pork.\n內用還是外帶？ | Nèiyòng háishì wàidài? | For here or to go?\n我要一杯熱咖啡。 | Wǒ yào yì bēi rè kāfēi. | I want a cup of hot coffee.', E'吃飯 | chīfàn | to have a meal\n便當 | biàndāng | lunch box\n飯 | fàn | cooked rice\n麵 | miàn | noodles\n雞肉 | jīròu | chicken (meat)\n豬肉 | zhūròu | pork\n牛肉 | niúròu | beef\n海鮮 | hǎixiān | seafood\n蛋 | dàn | egg\n青菜 | qīngcài | vegetables\n水果 | shuǐguǒ | fruit\n飲料 | yǐnliào | drink; beverage\n茶 | chá | tea\n咖啡 | kāfēi | coffee\n珍珠奶茶 | zhēnzhū nǎichá | bubble milk tea\n開水 | kāishuǐ | drinking water (boiled)\n冰 | bīng | iced; cold (drink)\n熱 | rè | hot\n辣 | là | spicy\n不辣 | bú là | not spicy\n甜 | tián | sweet\n鹹 | xián | salty\n好吃 | hǎochī | delicious\n餓 | è | hungry\n飽 | bǎo | full (after eating)\n渴 | kě | thirsty\n便利商店 | biànlì shāngdiàn | convenience store\n超商 | chāoshāng | convenience store (short form)\n店員 | diànyuán | store clerk\n微波 | wéibō | to microwave\n加熱 | jiārè | to heat up\n內用 | nèiyòng | to eat in\n外帶 | wàidài | to take out\n袋子 | dàizi | bag\n筷子 | kuàizi | chopsticks\n湯匙 | tāngchí | spoon\n碗 | wǎn | bowl\n杯 | bēi | cup (measure word)\n瓶 | píng | bottle (measure word)\n菜單 | càidān | menu\n點餐 | diǎncān | to order food\n份 | fèn | portion (measure word)\n素食 | sùshí | vegetarian food\n早餐 | zǎocān | breakfast\n午餐 | wǔcān | lunch\n晚餐 | wǎncān | dinner\n夜市 | yèshì | night market\n一共 | yígòng | in total', E'A：歡迎光臨！ | Huānyíng guānglín! | Welcome!\nB：你好，我要這個便當。 | Nǐ hǎo, wǒ yào zhège biàndāng. | Hello, I want this lunch box.\nA：要微波嗎？ | Yào wéibō ma? | Do you want it microwaved?\nB：要，謝謝。這個便當有豬肉嗎？ | Yào, xièxie. Zhège biàndāng yǒu zhūròu ma? | Yes, thanks. Does this lunch box have pork?\nA：沒有，這是雞肉便當。 | Méiyǒu, zhè shì jīròu biàndāng. | No, this is a chicken lunch box.\nB：好。我還要一瓶水。 | Hǎo. Wǒ hái yào yì píng shuǐ. | Okay. I also want a bottle of water.\nA：一共九十五塊。要袋子嗎？ | Yígòng jiǔshíwǔ kuài. Yào dàizi ma? | That is 95 dollars in total. Do you need a bag?\nB：不用，謝謝。 | Búyòng, xièxie. | No need, thanks.', E'到台灣生活', E'Living in Taiwan'),
    (7, E'交通與問路', E'Transportation & Directions', 12, E'目標：會搭公車、捷運、火車；會用悠遊卡；會問路和聽懂簡單的方向。句型：請問，……在哪裡？、……怎麼走？、往前直走，在……左轉／右轉、坐／搭＋交通工具＋去＋地方。發音：「遠不遠」中間的「不」唸 bù；「綠」lǜ 要嘟嘴；「捷運」jiéyùn 的 j、y 後面寫 u 其實唸 ü。文化：台灣搭捷運不可以吃東西、喝水；博愛座要讓給老人、孕婦和需要的人；機車很多，過馬路要看紅綠燈，走斑馬線。', E'Goals: take the bus, MRT and train, use the EasyCard, ask for directions and understand simple ones. Patterns: 請問，……在哪裡？ (Qǐngwèn, … zài nǎlǐ?), ……怎麼走？ (… zěnme zǒu?), 往前直走，在……左轉 (wǎng qián zhí zǒu, zài … zuǒ zhuǎn)／右轉 (yòu zhuǎn), 坐 (zuò)／搭 (dā) + transport + 去 (qù) + place. Pronunciation: 不 (bù) in 遠不遠 is bù; round your lips for lǜ; in jiéyùn the u after j and y is said like ü. Culture: no eating or drinking on the MRT in Taiwan. Give priority seats to older people, pregnant women and anyone who needs them. There are many scooters, so cross at the crosswalk when the light is green.', E'請問，捷運站在哪裡？ | Qǐngwèn, jiéyùnzhàn zài nǎlǐ? | Excuse me, where is the MRT station?\n往前直走，在路口右轉。 | Wǎng qián zhízǒu, zài lùkǒu yòu zhuǎn. | Go straight ahead and turn right at the intersection.\n我坐公車去市場。 | Wǒ zuò gōngchē qù shìchǎng. | I take the bus to the market.\n走路十分鐘。 | Zǒulù shí fēnzhōng. | It is a ten-minute walk.\n悠遊卡要儲值。 | Yōuyóukǎ yào chǔzhí. | The EasyCard needs to be topped up.', E'公車 | gōngchē | bus\n公車站 | gōngchēzhàn | bus stop\n捷運 | jiéyùn | MRT (metro)\n火車 | huǒchē | train\n高鐵 | gāotiě | high-speed rail\n計程車 | jìchéngchē | taxi\n機車 | jīchē | scooter; motorcycle\n腳踏車 | jiǎotàchē | bicycle\n走路 | zǒulù | to walk\n坐 | zuò | to sit; to ride (a vehicle)\n搭 | dā | to take (transport)\n騎 | qí | to ride (a scooter or bicycle)\n開車 | kāichē | to drive a car\n悠遊卡 | Yōuyóukǎ | EasyCard\n儲值 | chǔzhí | to top up\n票 | piào | ticket\n車站 | chēzhàn | station\n上車 | shàngchē | to get on\n下車 | xiàchē | to get off\n換車 | huànchē | to transfer\n哪裡 | nǎlǐ | where\n這裡 | zhèlǐ | here\n那裡 | nàlǐ | there\n左邊 | zuǒbiān | left side\n右邊 | yòubiān | right side\n前面 | qiánmiàn | in front\n後面 | hòumiàn | behind\n旁邊 | pángbiān | beside\n對面 | duìmiàn | opposite\n外面 | wàimiàn | outside\n裡面 | lǐmiàn | inside\n往 | wǎng | toward\n直走 | zhízǒu | to go straight\n轉 | zhuǎn | to turn\n遠 | yuǎn | far\n近 | jìn | near\n路口 | lùkǒu | intersection\n紅綠燈 | hónglǜdēng | traffic light\n地圖 | dìtú | map\n迷路 | mílù | to get lost\n怎麼 | zěnme | how\n多久 | duōjiǔ | how long\n分鐘 | fēnzhōng | minute (duration)\n市場 | shìchǎng | market\n博愛座 | bó''àizuò | priority seat', E'A：不好意思，請問火車站怎麼走？ | Bù hǎoyìsi, qǐngwèn huǒchēzhàn zěnme zǒu? | Excuse me, how do I get to the train station?\nB：往前直走，到紅綠燈左轉。 | Wǎng qián zhízǒu, dào hónglǜdēng zuǒ zhuǎn. | Go straight and turn left at the traffic light.\nA：遠不遠？ | Yuǎn bù yuǎn? | Is it far?\nB：不遠，走路五分鐘。 | Bù yuǎn, zǒulù wǔ fēnzhōng. | Not far, a five-minute walk.\nA：我要去台中，要在這裡買票嗎？ | Wǒ yào qù Táizhōng, yào zài zhèlǐ mǎi piào ma? | I am going to Taichung. Do I buy a ticket here?\nB：可以用悠遊卡，不用買票。 | Kěyǐ yòng Yōuyóukǎ, búyòng mǎi piào. | You can use the EasyCard, no ticket needed.\nA：太好了，謝謝您！ | Tài hǎo le, xièxie nín! | Great, thank you!\nB：不客氣，小心！ | Bú kèqì, xiǎoxīn! | You are welcome. Take care!', E'到台灣生活', E'Living in Taiwan'),
    (8, E'購物、錢與匯款', E'Shopping, Money & Remittance', 12, E'目標：會問價錢、殺價、付錢；會用提款機；會到匯款店把錢寄回菲律賓。句型：……多少錢？、太貴了，可以便宜一點嗎？、我要匯款回菲律賓、……是多少？。發音：「一千」唸 yìqiān、「一百」唸 yìbǎi（「一」在一聲、三聲前唸 yì）；「一次」唸 yí cì；「匯率」huìlǜ 的 l 後面要寫 ü。台灣讀音：「多少」台灣唸 duōshǎo；「便宜」台灣唸 piányí。文化：台灣說錢常用「塊」，寫的是「元」；買東西會拿到「發票」，要留好，可以對獎；匯款要找合法的銀行或匯款公司，收據要留著；提款卡密碼不可以告訴別人，仲介或雇主也不行。', E'Goals: ask prices, bargain and pay, use an ATM, and send money home to the Philippines. Patterns: ……多少錢？ (… duōshǎo qián?), 太貴了，可以便宜一點嗎？ (Tài guì le, kěyǐ piányí yìdiǎn ma?), 我要匯款回菲律賓 (Wǒ yào huìkuǎn huí Fēilǜbīn), ……是多少？ (… shì duōshǎo?). Pronunciation: 一千 is yìqiān and 一百 is yìbǎi (一 is yì before 1st and 3rd tones); 一次 is yí cì; write ü after l in huìlǜ. Taiwan readings: 多少 is duōshǎo and 便宜 is piányí. Culture: people say 塊 (kuài) for dollars and write 元 (yuán). Keep your receipts (發票 fāpiào); they are also lottery tickets. Send money only through licensed banks or remittance companies and keep the receipts. Never tell anyone your ATM PIN, not even your broker or employer.', E'這件衣服多少錢？ | Zhè jiàn yīfú duōshǎo qián? | How much is this piece of clothing?\n太貴了，可以便宜一點嗎？ | Tài guì le, kěyǐ piányí yìdiǎn ma? | It is too expensive. Can you make it cheaper?\n我要匯款回菲律賓。 | Wǒ yào huìkuǎn huí Fēilǜbīn. | I want to send money to the Philippines.\n今天的匯率是多少？ | Jīntiān de huìlǜ shì duōshǎo? | What is today''s exchange rate?\n密碼不可以告訴別人。 | Mìmǎ bù kěyǐ gàosù biérén. | Do not tell anyone your PIN.', E'買 | mǎi | to buy\n賣 | mài | to sell\n錢 | qián | money\n塊 | kuài | dollar (spoken)\n元 | yuán | dollar (written)\n台幣 | Táibì | New Taiwan dollar\n披索 | pīsuǒ | Philippine peso\n貴 | guì | expensive\n便宜 | piányí | cheap\n多少錢 | duōshǎo qián | how much (money)\n太 | tài | too (much)\n一點 | yìdiǎn | a little\n超市 | chāoshì | supermarket\n衣服 | yīfú | clothes\n件 | jiàn | piece (measure word for clothes)\n鞋子 | xiézi | shoes\n大 | dà | big\n小 | xiǎo | small\n顏色 | yánsè | color\n紅色 | hóngsè | red\n白色 | báisè | white\n黑色 | hēisè | black\n藍色 | lánsè | blue\n試穿 | shìchuān | to try on\n付錢 | fùqián | to pay\n現金 | xiànjīn | cash\n刷卡 | shuākǎ | to pay by card\n找錢 | zhǎoqián | to give change\n收據 | shōujù | receipt\n發票 | fāpiào | uniform invoice (receipt)\n打折 | dǎzhé | discount\n銀行 | yínháng | bank\n提款機 | tíkuǎnjī | ATM\n提款卡 | tíkuǎnkǎ | ATM card\n領錢 | lǐngqián | to withdraw money\n存錢 | cúnqián | to save money\n匯款 | huìkuǎn | to remit; remittance\n匯率 | huìlǜ | exchange rate\n手續費 | shǒuxùfèi | service fee\n寄錢 | jìqián | to send money\n家人 | jiārén | family\n帳戶 | zhànghù | bank account\n密碼 | mìmǎ | PIN; password\n告訴 | gàosù | to tell\n別人 | biérén | other people\n換 | huàn | to exchange; to change\n大約 | dàyuē | about; around', E'A：您好，我要寄錢給我家人。 | Nín hǎo, wǒ yào jìqián gěi wǒ jiārén. | Hello, I want to send money to my family.\nB：好。請給我你的居留證。 | Hǎo. Qǐng gěi wǒ nǐ de jūliúzhèng. | Okay. Please give me your residence permit.\nA：在這裡。今天的匯率是多少？ | Zài zhèlǐ. Jīntiān de huìlǜ shì duōshǎo? | Here it is. What is today''s exchange rate?\nB：一千台幣大約換一千八百披索。 | Yìqiān Táibì dàyuē huàn yìqiān bābǎi pīsuǒ. | 1,000 NT dollars is about 1,800 pesos.\nA：手續費多少錢？ | Shǒuxùfèi duōshǎo qián? | How much is the service fee?\nB：一次一百五十元。 | Yí cì yìbǎi wǔshí yuán. | 150 dollars each time.\nA：好，我要寄五千塊。 | Hǎo, wǒ yào jì wǔqiān kuài. | Okay, I want to send 5,000 dollars.\nB：請在這裡簽名。這是你的收據。 | Qǐng zài zhèlǐ qiānmíng. Zhè shì nǐ de shōujù. | Please sign here. This is your receipt.', E'到台灣生活', E'Living in Taiwan'),
    (9, E'上班、班別與聽懂指令', E'Shifts & Understanding Instructions', 14, E'目標：會說上下班時間和班別；聽懂主管簡單的指令並回答；聽不懂時會請對方再說一次。句型：請＋動作、先……再……、……完了（我做完了）、等一下。發音：「等一下」唸 děng yíxià；「再一次」唸 zài yí cì；「組長」zǔzhǎng 的 z 不捲舌、zh 要捲舌。文化：台灣職場很重視準時，上班前先打卡，遲到要先打電話說；主管交代事情，回答「好的」「知道了」，做完要回報；聽不懂一定要問，不要猜，猜錯更危險；下班時同事常說「辛苦了」，你也可以說。', E'Goals: talk about working hours and shifts, follow and answer simple instructions from a supervisor, and ask the speaker to repeat. Patterns: 請 (qǐng) + action, 先……再…… (xiān … zài …), …… + 完了 (wán le) (我做完了 wǒ zuò wán le), 等一下 (děng yíxià). Pronunciation: 等一下 is děng yíxià; 再一次 is zài yí cì; the z in zǔzhǎng is not curled, the zh is. Culture: Taiwan workplaces value punctuality. Clock in before work, and call ahead if you will be late. When a supervisor gives a task, answer 好的 (hǎo de) or 知道了 (zhīdào le) and report back when it is done. If you do not understand, ask instead of guessing, because guessing wrong is more dangerous. Coworkers often say 辛苦了 (xīnkǔ le) at the end of the day, and you can say it too.', E'我早上八點上班。 | Wǒ zǎoshàng bā diǎn shàngbān. | I start work at eight in the morning.\n上班要打卡。 | Shàngbān yào dǎkǎ. | You must clock in when you start work.\n請等一下，我馬上來。 | Qǐng děng yíxià, wǒ mǎshàng lái. | Please wait a moment, I am coming right away.\n組長，我做完了。 | Zǔzhǎng, wǒ zuòwán le. | Team leader, I am finished.\n對不起，我聽不懂，請再說一次。 | Duìbuqǐ, wǒ tīng bù dǒng, qǐng zài shuō yí cì. | Sorry, I do not understand. Please say it again.', E'上班 | shàngbān | to go to work\n下班 | xiàbān | to get off work\n打卡 | dǎkǎ | to clock in or out\n早班 | zǎobān | morning shift\n晚班 | wǎnbān | evening shift\n大夜班 | dàyèbān | night shift (overnight)\n輪班 | lúnbān | rotating shifts\n準時 | zhǔnshí | on time\n遲到 | chídào | to be late\n組長 | zǔzhǎng | team leader\n主管 | zhǔguǎn | supervisor\n同事 | tóngshì | coworker\n開始 | kāishǐ | to start\n做 | zuò | to do; to make\n做完 | zuòwán | to finish doing\n快 | kuài | fast\n快一點 | kuài yìdiǎn | a bit faster\n慢慢來 | mànmàn lái | take your time\n等一下 | děng yíxià | wait a moment\n馬上 | mǎshàng | right away\n好的 | hǎo de | okay; sure\n知道了 | zhīdào le | got it\n聽懂 | tīngdǒng | to understand (what is heard)\n看 | kàn | to look; to watch\n這樣 | zhèyàng | like this\n那樣 | nàyàng | like that\n對 | duì | correct; right\n錯 | cuò | wrong\n再一次 | zài yí cì | one more time\n幫 | bāng | to help (do something)\n拿來 | nálái | to bring over\n放 | fàng | to put\n休息時間 | xiūxí shíjiān | break time\n午休 | wǔxiū | lunch break\n工作服 | gōngzuòfú | work uniform\n會議 | huìyì | meeting\n訓練 | xùnliàn | training\n學 | xué | to learn\n教 | jiāo | to teach\n忙 | máng | busy\n累 | lèi | tired\n辛苦了 | xīnkǔ le | thanks for your hard work\n沒問題 | méi wèntí | no problem\n先 | xiān | first\n然後 | ránhòu | then; after that\n跟 | gēn | with; to (someone)', E'A：馬克，你今天上早班還是晚班？ | Mǎkè, nǐ jīntiān shàng zǎobān háishì wǎnbān? | Mark, are you on the morning or evening shift today?\nB：我上早班，八點到五點。 | Wǒ shàng zǎobān, bā diǎn dào wǔ diǎn. | I am on the morning shift, eight to five.\nA：好。你先把這些箱子放這裡。 | Hǎo. Nǐ xiān bǎ zhèxiē xiāngzi fàng zhèlǐ. | Okay. First put these boxes here.\nB：對不起，請說慢一點。 | Duìbuqǐ, qǐng shuō màn yìdiǎn. | Sorry, please speak more slowly.\nA：箱子，放這裡。這樣。 | Xiāngzi, fàng zhèlǐ. Zhèyàng. | Boxes, put them here. Like this.\nB：好的，我知道了。 | Hǎo de, wǒ zhīdào le. | Sure, I understand.\nA：做完了跟我說。 | Zuòwán le gēn wǒ shuō. | Tell me when you are done.\nB：組長，我做完了。 | Zǔzhǎng, wǒ zuòwán le. | Team leader, I am finished.\nA：很好，辛苦了！十二點午休。 | Hěn hǎo, xīnkǔ le! Shí''èr diǎn wǔxiū. | Very good, thanks for your hard work! Lunch break is at twelve.', E'工作基本', E'Work Basics'),
    (10, E'工作安全與警告標示', E'Work Safety & Warning Signs', 14, E'目標：看得懂常見的警告標示（危險、禁止、出口、小心地滑）；知道要戴哪些防護用品；受傷或火災時會喊出來、會報告。句型：一定要＋動作（一定要戴安全帽）、別／不要＋動作、小心＋東西、……了！（著火了！）。發音：「一定」唸 yídìng；「不要」唸 búyào；「著火了」的「著」唸 zháo。台灣讀音：「危險」台灣唸 wéixiǎn；「流血」台灣口語唸 liúxiě。文化：在台灣工地和工廠，安全規定很嚴格，沒戴安全帽、手套可能被罰款或不能上工；機器不正常要先按停止鈕再報告，不要自己修；受傷一定要說，可以申請職災保險。', E'Goals: read common warning signs (危險 wéixiǎn danger, 禁止 jìnzhǐ prohibited, 出口 chūkǒu exit, 小心地滑 Xiǎoxīn dì huá slippery floor), know which protective gear to wear, and shout for help and report when someone is hurt or there is a fire. Patterns: 一定要 (yídìng yào) + action (一定要戴安全帽 yídìng yào dài ānquánmào), 別 (bié)／不要 (búyào) + action, 小心 (xiǎoxīn) + thing, ……了！ (… le!) (著火了！ Zháohuǒ le!). Pronunciation: 一定 is yídìng; 不要 is búyào; 著 (zháo) in 著火了 is zháo. Taiwan readings: 危險 is wéixiǎn; 流血 is liúxiě in everyday speech. Culture: safety rules on Taiwan sites and in factories are strict, and you can be fined or sent home without a helmet or gloves. If a machine acts up, press the stop button first and then report it; do not fix it yourself. Always report injuries, because you can claim occupational injury insurance.', E'上班一定要戴安全帽。 | Shàngbān yídìng yào dài ānquánmào. | You must wear a safety helmet at work.\n別碰機器！ | Bié pèng jīqì! | Do not touch the machine!\n小心地滑。 | Xiǎoxīn dì huá. | Caution: slippery floor.\n著火了！快從緊急出口出去！ | Zháohuǒ le! Kuài cóng jǐnjí chūkǒu chūqù! | Fire! Get out through the emergency exit, quickly!\n我受傷了，流血了。 | Wǒ shòushāng le, liúxiě le. | I am hurt and bleeding.', E'危險 | wéixiǎn | ⚠️ sign: danger\n小心 | xiǎoxīn | be careful\n注意 | zhùyì | pay attention\n禁止 | jìnzhǐ | ⚠️ sign: prohibited\n禁止吸菸 | jìnzhǐ xīyān | ⚠️ sign: no smoking\n請勿觸摸 | qǐng wù chùmō | ⚠️ sign: do not touch\n閒人勿進 | xiánrén wù jìn | ⚠️ sign: staff only\n出口 | chūkǒu | ⚠️ sign: exit\n入口 | rùkǒu | ⚠️ sign: entrance\n緊急出口 | jǐnjí chūkǒu | ⚠️ sign: emergency exit\n小心地滑 | xiǎoxīn dì huá | ⚠️ sign: slippery floor\n高壓電 | gāoyādiàn | ⚠️ sign: high voltage\n有毒 | yǒudú | ⚠️ sign: toxic\n易燃 | yìrán | ⚠️ sign: flammable\n安全 | ānquán | safe; safety\n安全帽 | ānquánmào | safety helmet\n手套 | shǒutào | gloves\n口罩 | kǒuzhào | face mask\n護目鏡 | hùmùjìng | safety goggles\n耳塞 | ěrsāi | earplugs\n安全鞋 | ānquánxié | safety shoes\n戴 | dài | to wear (helmet, gloves, mask)\n穿 | chuān | to wear (clothes, shoes)\n別 | bié | do not\n不要 | búyào | do not; do not want\n一定 | yídìng | definitely; must\n機器 | jīqì | machine\n按鈕 | ànniǔ | button\n停 | tíng | to stop\n碰 | pèng | to touch; to bump\n火 | huǒ | fire\n著火了 | zháohuǒ le | there is a fire\n滅火器 | mièhuǒqì | fire extinguisher\n逃生 | táoshēng | to escape (to safety)\n受傷 | shòushāng | to get hurt\n流血 | liúxiě | to bleed\n痛 | tòng | painful\n急救箱 | jíjiùxiāng | first-aid kit\n救命 | jiùmìng | help! (emergency)\n摔倒 | shuāidǎo | to fall down\n化學藥品 | huàxué yàopǐn | chemicals\n報告 | bàogào | to report\n趕快 | gǎnkuài | hurry up\n門口 | ménkǒu | doorway; entrance area\n從 | cóng | from; through', E'A：馬克，你的手套呢？ | Mǎkè, nǐ de shǒutào ne? | Mark, where are your gloves?\nB：對不起，我忘了。 | Duìbuqǐ, wǒ wàng le. | Sorry, I forgot.\nA：這台機器很危險，一定要戴手套。 | Zhè tái jīqì hěn wéixiǎn, yídìng yào dài shǒutào. | This machine is dangerous. You must wear gloves.\nB：好，我馬上戴。 | Hǎo, wǒ mǎshàng dài. | Okay, I will put them on right away.\nA：機器有問題就按這個紅色按鈕。 | Jīqì yǒu wèntí jiù àn zhège hóngsè ànniǔ. | If the machine has a problem, press this red button.\nB：按紅色按鈕，機器會停。 | Àn hóngsè ànniǔ, jīqì huì tíng. | Press the red button and the machine stops.\nA：對。受傷了要馬上跟我報告。 | Duì. Shòushāng le yào mǎshàng gēn wǒ bàogào. | Right. If you get hurt, report it to me right away.\nB：知道了。急救箱在哪裡？ | Zhīdào le. Jíjiùxiāng zài nǎlǐ? | Got it. Where is the first-aid kit?\nA：在門口旁邊。 | Zài ménkǒu pángbiān. | Next to the door.', E'工作基本', E'Work Basics'),
    (11, E'薪水、加班、請假與休假', E'Pay, Overtime, Leave & Days Off', 12, E'目標：看懂薪資單上的項目；會問加班費和扣款；會請病假、事假，會說要休假的日子。句型：我想請假＋時間、……好像不對、為什麼……？、每個月＋日期＋發薪水。發音：「不對」唸 bú duì；「一天」唸 yì tiān；「加班費」jiābānfèi 三個字都要清楚。文化：在台灣，加班要付加班費，薪資單上會寫基本工資、加班費和扣的錢（健保、勞保、伙食費、住宿費）；看不懂可以請仲介或打一九五五問；請假最好先說，生病要拿醫生證明；過年等國定假日的安排要事先問清楚。', E'Goals: read the items on your payslip, ask about overtime pay and deductions, ask for sick or personal leave, and say which days you want off. Patterns: 我想請假 (wǒ xiǎng qǐngjià) + time, ……好像不對 (… hǎoxiàng búduì), 為什麼……？ (wèishénme …?), 每個月 (měi ge yuè) + date + 發薪水 (fā xīnshuǐ). Pronunciation: 不對 is bú duì; 一天 is yì tiān; say all three syllables of jiābānfèi clearly. Culture: overtime must be paid in Taiwan. Your payslip lists the basic wage, overtime pay and deductions (health insurance, labor insurance, food and lodging fees). If you do not understand it, ask your broker or call 1955. Ask for leave early, bring a doctor''s note when you are sick, and ask about national holidays such as Lunar New Year in advance.', E'我想請假一天。 | Wǒ xiǎng qǐngjià yì tiān. | I would like to take one day off.\n這個月的加班費不對。 | Zhège yuè de jiābānfèi bú duì. | This month''s overtime pay is not right.\n請問，為什麼扣這麼多？ | Qǐngwèn, wèishénme kòu zhème duō? | Excuse me, why is so much deducted?\n每個月五號發薪水。 | Měi ge yuè wǔ hào fā xīnshuǐ. | Salary is paid on the 5th of every month.\n我生病了，要請病假。 | Wǒ shēngbìng le, yào qǐng bìngjià. | I am sick and need sick leave.', E'薪水 | xīnshuǐ | salary\n發薪日 | fāxīnrì | payday\n薪資單 | xīnzīdān | payslip\n月薪 | yuèxīn | monthly salary\n時薪 | shíxīn | hourly wage\n基本工資 | jīběn gōngzī | basic wage\n加班 | jiābān | to work overtime\n加班費 | jiābānfèi | overtime pay\n雙倍 | shuāngbèi | double\n扣 | kòu | to deduct\n伙食費 | huǒshífèi | food fee\n住宿費 | zhùsùfèi | lodging fee\n健保 | jiànbǎo | national health insurance\n勞保 | láobǎo | labor insurance\n稅 | shuì | tax\n請假 | qǐngjià | to ask for leave\n病假 | bìngjià | sick leave\n事假 | shìjià | personal leave\n休假 | xiūjià | day off; vacation\n放假 | fàngjià | to have a holiday\n年假 | niánjià | annual leave\n補休 | bǔxiū | compensatory day off\n國定假日 | guódìng jiàrì | national holiday\n過年 | guònián | Lunar New Year\n生病 | shēngbìng | to get sick\n工時 | gōngshí | working hours\n一天 | yì tiān | one day\n每個月 | měi ge yuè | every month\n算 | suàn | to calculate\n算錯 | suàncuò | to miscalculate\n不對 | bú duì | incorrect\n少 | shǎo | few; less\n多 | duō | many; more\n夠 | gòu | enough\n同意 | tóngyì | to agree\n證明 | zhèngmíng | certificate; proof\n回國 | huíguó | to return to one''s country\n機票 | jīpiào | plane ticket\n申請 | shēnqǐng | to apply\n老闆娘 | lǎobǎnniáng | lady boss; boss''s wife\n清楚 | qīngchǔ | clear\n好像 | hǎoxiàng | it seems\n為什麼 | wèishénme | why\n只 | zhǐ | only\n寫 | xiě | to write\n補 | bǔ | to make up (pay back)', E'A：老闆，不好意思，我想跟您請假。 | Lǎobǎn, bù hǎoyìsi, wǒ xiǎng gēn nín qǐngjià. | Boss, excuse me, I would like to ask you for leave.\nB：什麼時候？ | Shénme shíhòu? | When?\nA：下個星期五，我要去辦居留證。 | Xià ge xīngqíwǔ, wǒ yào qù bàn jūliúzhèng. | Next Friday. I need to renew my residence permit.\nB：好，可以。 | Hǎo, kěyǐ. | Okay, that is fine.\nA：還有，這個月的薪資單，加班費好像少了。 | Háiyǒu, zhège yuè de xīnzīdān, jiābānfèi hǎoxiàng shǎo le. | Also, on this month''s payslip, the overtime pay seems short.\nB：你加班幾個小時？ | Nǐ jiābān jǐ ge xiǎoshí? | How many hours of overtime did you work?\nA：二十個小時。這裡只寫十五個小時。 | Èrshí ge xiǎoshí. Zhèlǐ zhǐ xiě shíwǔ ge xiǎoshí. | Twenty hours. It only says fifteen hours here.\nB：我看一下。對不起，我們算錯了，下個月補給你。 | Wǒ kàn yíxià. Duìbuqǐ, wǒmen suàncuò le, xià ge yuè bǔ gěi nǐ. | Let me see. Sorry, we miscalculated. We will pay you the rest next month.\nA：謝謝老闆！ | Xièxie lǎobǎn! | Thank you, boss!', E'工作基本', E'Work Basics'),
    (12, E'看護（一）：起床、吃飯與吃藥', E'Caregiving 1: Getting Up, Meals & Medicine', 14, E'目標：會叫長輩起床、扶他坐起來、刷牙洗臉；會餵飯、提醒吃藥；會問長輩舒不舒服。句型：我扶您＋動作、慢慢＋動作（慢慢吃）、飯前／飯後吃藥、您要不要……？。發音：「要不要」唸 yào bú yào；「不舒服」唸 bù shūfú；「女兒」要寫隔音符號 nǚ''ér。文化：台灣長輩喜歡被尊稱「阿公」「阿嬤」，對長輩說話用「您」；吃藥的時間和份量要照藥袋上寫的，不要自己加減；長輩吞東西慢，要讓他坐好、慢慢吃，避免嗆到；有任何不一樣都要告訴家屬。', E'Goals: wake an older person, help them sit up, brush their teeth and wash their face, feed them, remind them to take medicine, and ask whether they feel well. Patterns: 我扶您 (wǒ fú nín) + action, 慢慢 (mànmàn) + action (慢慢吃 mànmàn chī), 飯前 (fànqián)／飯後吃藥 (fàn hòu chī yào), 您要不要……？ (nín yào bú yào …?). Pronunciation: 要不要 is yào bú yào; 不舒服 is bù shūfú; write the apostrophe in nǚ''ér. Culture: older people in Taiwan like to be called 阿公 (āgōng) and 阿嬤 (āmà), so use 您 (nín) when you speak to them. Give medicine at the times and doses printed on the medicine bag, never more or less. Older people swallow slowly, so help them sit upright and eat slowly so they do not choke. Tell the family about any change.', E'阿嬤，早安！我們起床了。 | Āmà, zǎo''ān! Wǒmen qǐchuáng le. | Good morning, Grandma! Time to get up.\n飯後要吃藥。 | Fànhòu yào chīyào. | Take the medicine after meals.\n阿公，慢慢吃。 | Āgōng, mànmàn chī. | Grandpa, eat slowly.\n您哪裡不舒服？ | Nín nǎlǐ bù shūfú? | Where do you feel unwell?\n這個藥一天吃三次。 | Zhège yào yì tiān chī sān cì. | Take this medicine three times a day.', E'起床 | qǐchuáng | to get up\n睡覺 | shuìjiào | to go to bed\n起來 | qǐlái | to get up (from lying or sitting)\n扶 | fú | to support (with your hands)\n坐起來 | zuò qǐlái | to sit up\n站起來 | zhàn qǐlái | to stand up\n慢慢 | mànmàn | slowly\n輪椅 | lúnyǐ | wheelchair\n助行器 | zhùxíngqì | walker\n拐杖 | guǎizhàng | cane\n餵 | wèi | to feed\n吃藥 | chīyào | to take medicine\n藥 | yào | medicine\n藥袋 | yàodài | medicine bag\n飯前 | fànqián | before meals\n飯後 | fànhòu | after meals\n稀飯 | xīfàn | rice porridge\n喝水 | hēshuǐ | to drink water\n吸管 | xīguǎn | straw\n擦 | cā | to wipe\n嘴巴 | zuǐbā | mouth\n牙齒 | yáchǐ | teeth\n刷牙 | shuāyá | to brush teeth\n假牙 | jiǎyá | dentures\n洗臉 | xǐliǎn | to wash one''s face\n毛巾 | máojīn | towel\n衛生紙 | wèishēngzhǐ | tissue; toilet paper\n眼鏡 | yǎnjìng | glasses\n電視 | diànshì | television\n遙控器 | yáokòngqì | remote control\n舒服 | shūfú | comfortable\n不舒服 | bù shūfú | unwell\n要不要 | yào bú yào | do you want (to)?\n想 | xiǎng | to want to; to miss\n吞 | tūn | to swallow\n咬 | yǎo | to bite; to chew\n軟 | ruǎn | soft\n硬 | yìng | hard\n嗆到 | qiàngdào | to choke\n指甲 | zhǐjiǎ | fingernails\n梳頭 | shūtóu | to comb hair\n家屬 | jiāshǔ | family members (of a patient)\n兒子 | érzi | son\n女兒 | nǚ''ér | daughter\n孫子 | sūnzi | grandchild\n包 | bāo | pack (measure word for medicine)\n溫 | wēn | lukewarm', E'A：阿嬤，早安！睡得好嗎？ | Āmà, zǎo''ān! Shuì de hǎo ma? | Good morning, Grandma! Did you sleep well?\nB：還好。我想起來。 | Hái hǎo. Wǒ xiǎng qǐlái. | Not bad. I want to get up.\nA：好，我扶您。慢慢坐起來。 | Hǎo, wǒ fú nín. Mànmàn zuò qǐlái. | Okay, I will help you. Sit up slowly.\nB：我要先刷牙。 | Wǒ yào xiān shuāyá. | I want to brush my teeth first.\nA：好。刷完牙，我們吃稀飯。 | Hǎo. Shuāwán yá, wǒmen chī xīfàn. | Okay. After brushing, we will eat porridge.\nB：今天的藥呢？ | Jīntiān de yào ne? | What about today''s medicine?\nA：飯後吃。這是早上的藥，一包。 | Fànhòu chī. Zhè shì zǎoshàng de yào, yì bāo. | After the meal. This is the morning medicine, one pack.\nB：好。水太燙了。 | Hǎo. Shuǐ tài tàng le. | Okay. The water is too hot.\nA：對不起，我換溫的給您。 | Duìbuqǐ, wǒ huàn wēn de gěi nín. | Sorry, I will get you lukewarm water.', E'看護', E'Caregiving'),
    (13, E'看護（二）：洗澡、如廁、翻身與量血壓', E'Caregiving 2: Bathing, Toileting, Turning & Blood Pressure', 14, E'目標：會幫長輩洗澡、換尿布、上廁所、翻身拍背；會量血壓、體溫並記錄；會跟家屬報告身體狀況。句型：我幫您＋動作、……有點＋形容詞（有點高）、要不要＋動作？、如果……，就……。發音：「一百四十」唸 yìbǎi sìshí；「有點」yǒudiǎn 兩個三聲連在一起，前面唸二聲；「咳嗽」台灣唸 késòu。台灣讀音：「血壓」「血糖」台灣口語唸 xiě，字典讀音也有 xuè。文化：幫長輩洗澡前先試水溫、關好門窗，保護長輩隱私；翻身大約兩個小時一次，可以預防褥瘡；長輩跌倒不要馬上拉起來，先看有沒有受傷，再叫家屬或打一一九。', E'Goals: help an older person bathe, change diapers, use the toilet, turn over and get back pats, measure and record blood pressure and temperature, and report their condition to the family. Patterns: 我幫您 (wǒ bāng nín) + action, …… + 有點 (yǒudiǎn) + adjective (有點高 yǒudiǎn gāo), 要不要 (yào bú yào) + action？, 如果……，就…… (rúguǒ …, jiù …). Pronunciation: 一百四十 is yìbǎi sìshí; yǒudiǎn has two 3rd tones, so the first is said as a 2nd tone; 咳嗽 is késòu in Taiwan. Taiwan reading: 血 (xiě) in 血壓 (xiěyā) and 血糖 is xiě in everyday speech, and the dictionary also gives xuè. Culture: test the water and close doors and windows before a bath to protect the person''s privacy. Turn bedridden people about every two hours to prevent bedsores. If an older person falls, do not pull them up right away; check for injuries first, then call the family or 119.', E'阿公，我幫您翻身。 | Āgōng, wǒ bāng nín fānshēn. | Grandpa, I will help you turn over.\n水溫可以嗎？ | Shuǐwēn kěyǐ ma? | Is the water temperature okay?\n阿嬤的血壓一百四十，有點高。 | Āmà de xiěyā yìbǎi sìshí, yǒudiǎn gāo. | Grandma''s blood pressure is 140, a bit high.\n要上廁所嗎？ | Yào shàng cèsuǒ ma? | Do you need to use the toilet?\n阿公今天沒有大便，我要跟家屬說。 | Āgōng jīntiān méiyǒu dàbiàn, wǒ yào gēn jiāshǔ shuō. | Grandpa has not had a bowel movement today; I must tell the family.', E'洗頭 | xǐtóu | to wash hair\n水溫 | shuǐwēn | water temperature\n冷 | lěng | cold\n換尿布 | huàn niàobù | to change a diaper\n尿布 | niàobù | diaper\n上廁所 | shàng cèsuǒ | to use the toilet\n便盆 | biànpén | bedpan\n尿尿 | niàoniào | to pee\n大便 | dàbiàn | to poop; stool\n便秘 | biànmì | constipation\n拉肚子 | lādùzi | diarrhea\n翻身 | fānshēn | to turn over (in bed)\n拍背 | pāibèi | to pat the back\n抽痰 | chōután | to suction phlegm\n痰 | tán | phlegm\n咳嗽 | késòu | to cough\n量 | liáng | to measure\n血壓 | xiěyā | blood pressure\n血壓計 | xiěyājì | blood pressure monitor\n體溫 | tǐwēn | body temperature\n發燒 | fāshāo | fever; to have a fever\n度 | dù | degree\n心跳 | xīntiào | heart rate\n血糖 | xiětáng | blood sugar\n記錄 | jìlù | to record; record\n正常 | zhèngcháng | normal\n高 | gāo | high; tall\n低 | dī | low\n有點 | yǒudiǎn | a bit; slightly\n復健 | fùjiàn | rehabilitation\n運動 | yùndòng | exercise\n散步 | sànbù | to take a walk\n公園 | gōngyuán | park\n曬太陽 | shài tàiyáng | to sit in the sun\n跌倒 | diédǎo | to fall (and get hurt)\n傷口 | shāngkǒu | wound\n藥膏 | yàogāo | ointment\n換藥 | huànyào | to change a dressing\n乳液 | rǔyì | lotion\n擦乾 | cāgān | to dry off\n襪子 | wàzi | socks\n按摩 | ànmó | massage\n如果 | rúguǒ | if\n回報 | huíbào | to report back\n褥瘡 | rùchuāng | bedsore\n隱私 | yǐnsī | privacy', E'A：陳小姐，阿嬤今天體溫三十八度。 | Chén xiǎojiě, āmà jīntiān tǐwēn sānshíbā dù. | Ms. Chen, Grandma''s temperature is 38 degrees today.\nB：發燒了？她有咳嗽嗎？ | Fāshāo le? Tā yǒu késòu ma? | She has a fever? Is she coughing?\nA：有一點咳嗽，痰很多。我幫她拍背了。 | Yǒu yìdiǎn késòu, tán hěn duō. Wǒ bāng tā pāibèi le. | A little cough, with a lot of phlegm. I patted her back.\nB：血壓呢？ | Xiěyā ne? | What about her blood pressure?\nA：一百三十，八十，正常。 | Yìbǎi sānshí, bāshí, zhèngcháng. | 130 over 80, normal.\nB：好。下午再量一次。 | Hǎo. Xiàwǔ zài liáng yí cì. | Okay. Measure it again in the afternoon.\nA：好的。我也會記錄。 | Hǎo de. Wǒ yě huì jìlù. | Sure. I will also write it down.\nB：如果還發燒，我們去看醫生。 | Rúguǒ hái fāshāo, wǒmen qù kàn yīshēng. | If she still has a fever, we will see a doctor.\nA：知道了，我會注意。 | Zhīdào le, wǒ huì zhùyì. | Understood, I will keep an eye on her.', E'看護', E'Caregiving'),
    (14, E'家事：打掃、洗衣、煮飯與照顧小孩', E'Housework: Cleaning, Laundry, Cooking & Childcare', 14, E'目標：聽懂雇主交代的家事；會說做完了什麼；會問衣服怎麼洗、晚餐煮什麼；會接送小孩。句型：先……再……、……要＋動作＋在＋地方（衣服要晾在陽台）、……好了（掃好了）、……還是……？。發音：「掃地」sǎodì、「掃把」sàobǎ 的「掃」聲調不同；「和」台灣口語常唸 hàn；「寶寶」第二個字唸輕聲。文化：台灣家庭進門要脫鞋；不同的抹布分開用（廚房、廁所不混用）；台灣常下雨，衣服常晾在陽台或用烘衣機；照顧小孩時不要讓他一個人在家，也不要給陌生人開門；用瓦斯煮飯，離開廚房前要關火。', E'Goals: understand household tasks from your employer, say what you have finished, ask how to wash the clothes and what to cook for dinner, and take children to and from school. Patterns: 先……再…… (xiān … zài …), …… + 要 (yào) + action + 在 (zài) + place (衣服要晾在陽台 Yīfú yào liàng zài yángtái), …… + 好了 (hǎo le) (掃好了 sǎo hǎo le), ……還是……？ (… háishì …?). Pronunciation: 掃 (sǎo) has different tones in 掃地 sǎodì and 掃把 sàobǎ; 和 (hàn) is often hàn in Taiwan speech; the second 寶 (bǎo) in 寶寶 (bǎobao) is neutral. Culture: take off your shoes at the door in Taiwan homes. Keep separate rags for the kitchen and the bathroom. It rains a lot, so clothes are often dried on the balcony or in a dryer. Never leave a child home alone, and do not open the door to strangers. Turn off the gas before you leave the kitchen.', E'太太，客廳我掃好了。 | Tàitai, kètīng wǒ sǎohǎo le. | Ma''am, I have finished sweeping the living room.\n衣服要晾在陽台。 | Yīfú yào liàng zài yángtái. | Hang the clothes on the balcony.\n我四點去學校接小孩。 | Wǒ sì diǎn qù xuéxiào jiē xiǎohái. | I pick up the children at school at four.\n今天晚上煮什麼？ | Jīntiān wǎnshàng zhǔ shénme? | What shall I cook tonight?\n白色的衣服要分開洗。 | Báisè de yīfú yào fēnkāi xǐ. | Wash white clothes separately.', E'打掃 | dǎsǎo | to clean\n掃地 | sǎodì | to sweep the floor\n拖地 | tuōdì | to mop the floor\n掃把 | sàobǎ | broom\n拖把 | tuōbǎ | mop\n抹布 | mābù | rag\n吸塵器 | xīchénqì | vacuum cleaner\n洗碗 | xǐwǎn | to wash dishes\n洗碗精 | xǐwǎnjīng | dish soap\n洗衣服 | xǐ yīfú | to do the laundry\n洗衣精 | xǐyījīng | laundry detergent\n晾衣服 | liàng yīfú | to hang clothes to dry\n收衣服 | shōu yīfú | to bring in the laundry\n摺 | zhé | to fold\n燙衣服 | tàng yīfú | to iron clothes\n衣架 | yījià | clothes hanger\n烘衣機 | hōngyījī | clothes dryer\n煮飯 | zhǔfàn | to cook\n炒 | chǎo | to stir-fry\n切 | qiē | to cut\n洗菜 | xǐcài | to wash vegetables\n鍋子 | guōzi | pot\n刀子 | dāozi | knife\n瓦斯 | wǎsī | gas (for cooking)\n關火 | guānhuǒ | to turn off the stove\n電鍋 | diànguō | rice cooker\n買菜 | mǎicài | to buy groceries\n小孩 | xiǎohái | child\n寶寶 | bǎobao | baby\n奶瓶 | nǎipíng | baby bottle\n泡奶 | pàonǎi | to prepare milk (formula)\n學校 | xuéxiào | school\n功課 | gōngkè | homework\n玩 | wán | to play\n哭 | kū | to cry\n狗 | gǒu | dog\n遛狗 | liùgǒu | to walk the dog\n馬桶 | mǎtǒng | toilet bowl\n陽台 | yángtái | balcony\n客廳 | kètīng | living room\n房子 | fángzi | house\n整理 | zhěnglǐ | to tidy up\n分開 | fēnkāi | separately; to separate\n陌生人 | mòshēngrén | stranger\n脫鞋 | tuōxié | to take off shoes', E'A：太太，今天要做什麼？ | Tàitai, jīntiān yào zuò shénme? | Ma''am, what should I do today?\nB：先打掃客廳，再洗衣服。 | Xiān dǎsǎo kètīng, zài xǐ yīfú. | Clean the living room first, then do the laundry.\nA：好。白色的衣服要分開洗嗎？ | Hǎo. Báisè de yīfú yào fēnkāi xǐ ma? | Okay. Should I wash white clothes separately?\nB：對，分開洗。下午會下雨，衣服晾在裡面。 | Duì, fēnkāi xǐ. Xiàwǔ huì xiàyǔ, yīfú liàng zài lǐmiàn. | Yes, separately. It will rain this afternoon, so hang the clothes inside.\nA：知道了。晚上要煮飯嗎？ | Zhīdào le. Wǎnshàng yào zhǔfàn ma? | Got it. Should I cook dinner?\nB：要。煮青菜和魚。弟弟不吃辣。 | Yào. Zhǔ qīngcài hàn yú. Dìdi bù chī là. | Yes. Cook vegetables and fish. Our little boy does not eat spicy food.\nA：好。四點我去接弟弟。 | Hǎo. Sì diǎn wǒ qù jiē dìdi. | Okay. I will pick him up at four.\nB：謝謝你，辛苦了。 | Xièxie nǐ, xīnkǔ le. | Thank you, I appreciate your hard work.', E'家庭幫傭', E'Domestic Work'),
    (15, E'工廠：機器、產線與品管', E'Factory: Machines, Production Lines & Quality Control', 14, E'目標：會說產線上的東西和工作；會報告機台故障、不良品數量；聽懂包裝、貼標籤、搬貨的指令。句型：……卡住了／壞了、……放＋地方、一箱放＋數量＋個、先＋動作，再＋動作。發音：「一箱」唸 yì xiāng；「一直」唸 yìzhí；「不良品」的「不」在二聲前唸 bù。台灣讀音：「品質」台灣唸 pǐnzhí。文化：台灣工廠常說「良品」「不良品」，不良品要分開放、寫在報表上，不能混在良品裡；機台卡住要先關機再處理，手不可以伸進機器；換班時要把今天的數量和問題交代清楚；搬重的東西要用推車或請同事幫忙，彎膝蓋、不要彎腰。', E'Goals: name things and tasks on a production line, report a broken machine and the number of defective items, and follow instructions for packing, labeling and moving goods. Patterns: …… + 卡住了 (qiǎzhù le)／壞了 (huài le), …… + 放 (fàng) + place, 一箱放 (yì xiāng fàng) + number + 個 (ge), 先 (xiān) + action，再 (zài) + action. Pronunciation: 一箱 is yì xiāng; 一直 is yìzhí; 不 (bù) in 不良品 is bù before a 2nd tone. Taiwan reading: 品質 is pǐnzhí. Culture: Taiwan factories talk about 良品 (liángpǐn) (good items) and 不良品 (bùliángpǐn) (defects). Keep defects apart, write them on the report form and never mix them with good items. If a machine jams, shut it down before you touch it, and never put your hand inside. At shift change, pass on today''s numbers and problems clearly. Use a trolley or ask a coworker to help with heavy things, and lift with your knees, not your back.', E'這個是不良品，放這邊。 | Zhège shì bùliángpǐn, fàng zhèbiān. | This one is defective. Put it over here.\n機台卡住了，請叫組長。 | Jītái qiǎzhù le, qǐng jiào zǔzhǎng. | The machine is jammed. Please call the team leader.\n一箱放二十個。 | Yì xiāng fàng èrshí ge. | Put twenty in each box.\n標籤要貼好，對齊。 | Biāoqiān yào tiēhǎo, duìqí. | Stick the labels on properly and line them up.\n今天的目標是五百個。 | Jīntiān de mùbiāo shì wǔbǎi ge. | Today''s target is five hundred pieces.', E'工廠 | gōngchǎng | factory\n產線 | chǎnxiàn | production line\n機台 | jītái | machine (workstation)\n開機 | kāijī | to start a machine\n關機 | guānjī | to shut down a machine\n開關 | kāiguān | switch\n零件 | língjiàn | parts\n材料 | cáiliào | materials\n產品 | chǎnpǐn | product\n良品 | liángpǐn | good product\n不良品 | bùliángpǐn | defective product\n品管 | pǐnguǎn | quality control\n品質 | pǐnzhí | quality\n檢查 | jiǎnchá | to inspect; to check\n數量 | shùliàng | quantity\n數 | shǔ | to count\n包裝 | bāozhuāng | to pack; packaging\n貼 | tiē | to stick\n標籤 | biāoqiān | label\n紙箱 | zhǐxiāng | carton\n搬 | bān | to move (carry)\n推車 | tuīchē | trolley\n堆高機 | duīgāojī | forklift\n倉庫 | cāngkù | warehouse\n螺絲 | luósī | screw\n工具 | gōngjù | tool\n剪刀 | jiǎndāo | scissors\n膠帶 | jiāodài | tape\n尺寸 | chǐcùn | size (dimensions)\n重 | zhòng | heavy\n輕 | qīng | light (in weight)\n對齊 | duìqí | to align\n漏 | lòu | to leak\n卡住 | qiǎzhù | stuck; jammed\n故障 | gùzhàng | breakdown; malfunction\n維修 | wéixiū | to repair (maintenance)\n噪音 | zàoyīn | noise\n目標 | mùbiāo | target\n產量 | chǎnliàng | output\n清潔 | qīngjié | to clean (an area)\n報表 | bàobiǎo | report form\n換班 | huànbān | to change shifts\n工號 | gōnghào | employee number\n一直 | yìzhí | continuously; all the time\n這邊 | zhèbiān | this side; over here\n那邊 | nàbiān | that side; over there\n台 | tái | measure word for machines', E'A：馬克，這台機台怎麼了？ | Mǎkè, zhè tái jītái zěnme le? | Mark, what is wrong with this machine?\nB：組長，它卡住了，一直有噪音。 | Zǔzhǎng, tā qiǎzhù le, yìzhí yǒu zàoyīn. | Team leader, it is jammed and keeps making noise.\nA：先關機，不要用手碰。 | Xiān guānjī, búyào yòng shǒu pèng. | Shut it down first. Do not touch it with your hands.\nB：好，我關機了。 | Hǎo, wǒ guānjī le. | Okay, I have shut it down.\nA：我叫維修的人來。你先去檢查那些產品。 | Wǒ jiào wéixiū de rén lái. Nǐ xiān qù jiǎnchá nàxiē chǎnpǐn. | I will call maintenance. Go and check those products first.\nB：有三個不良品。 | Yǒu sān ge bùliángpǐn. | There are three defective ones.\nA：放紅色的箱子，寫在報表上。 | Fàng hóngsè de xiāngzi, xiě zài bàobiǎo shàng. | Put them in the red box and write it on the report form.\nB：好的。良品要包裝嗎？ | Hǎo de. Liángpǐn yào bāozhuāng ma? | Sure. Should I pack the good ones?\nA：要，一箱二十個，貼標籤。 | Yào, yì xiāng èrshí ge, tiē biāoqiān. | Yes, twenty per box, and stick on the labels.', E'工廠', E'Factory Work'),
    (16, E'農業：農場、溫室與採收', E'Farm Work: Fields, Greenhouses & Harvest', 12, E'目標：會說農場、菜園、溫室和雞舍的工作；聽懂澆水、施肥、除草、採收的指令；會保護自己不中暑、不被農藥傷害。句型：先＋動作（早上先澆水）、……可以採了、……要戴＋防護用品、小心＋危險。發音：「草」cǎo、「採」cǎi 的 c 要送氣，像「ts」；「鋤頭」的「頭」唸輕聲 chútou；「和」台灣口語常唸 hàn。文化：台灣夏天很熱，農事最好在早上或傍晚做，中午要休息、多喝水；噴農藥一定要戴口罩、手套，噴完要洗手、換衣服，不可以在噴藥的地方吃東西；颱風前要幫忙固定溫室、收好工具。', E'Goals: talk about work on farms, vegetable gardens, greenhouses and chicken coops, follow instructions for watering, fertilizing, weeding and harvesting, and protect yourself from heatstroke and pesticides. Patterns: 先 (xiān) + action (早上先澆水 Zǎoshàng xiān jiāoshuǐ), …… + 可以採了 (kěyǐ cǎi le), …… + 要戴 (yào dài) + protective gear, 小心 (xiǎoxīn) + danger. Pronunciation: the c in cǎo and cǎi is aspirated, like "ts" with a puff of air; 頭 (tóu) in 鋤頭 (chútou) is neutral (chútou); 和 (hàn) is often hàn in Taiwan speech. Culture: Taiwan summers are hot, so farm work is best done in the morning or late afternoon; rest at noon and drink plenty of water. Always wear a mask and gloves when spraying pesticide, wash your hands and change clothes afterwards, and never eat where you have sprayed. Before a typhoon, help secure the greenhouse and put tools away.', E'早上先澆水。 | Zǎoshàng xiān jiāoshuǐ. | Water the plants first thing in the morning.\n這些番茄紅了，可以採了。 | Zhèxiē fānqié hóng le, kěyǐ cǎi le. | These tomatoes are red; they can be picked.\n噴農藥要戴口罩和手套。 | Pēn nóngyào yào dài kǒuzhào hàn shǒutào. | Wear a mask and gloves when spraying pesticide.\n天氣很熱，要多喝水，小心中暑。 | Tiānqì hěn rè, yào duō hē shuǐ, xiǎoxīn zhòngshǔ. | It is hot. Drink plenty of water and watch out for heatstroke.\n雞舍的蛋每天要撿。 | Jīshè de dàn měitiān yào jiǎn. | Collect the eggs in the chicken coop every day.', E'農場 | nóngchǎng | farm\n田 | tián | field\n菜園 | càiyuán | vegetable garden\n溫室 | wēnshì | greenhouse\n種 | zhòng | to plant\n種子 | zhǒngzi | seed\n澆水 | jiāoshuǐ | to water (plants)\n水管 | shuǐguǎn | hose\n肥料 | féiliào | fertilizer\n施肥 | shīféi | to fertilize\n農藥 | nóngyào | pesticide\n噴 | pēn | to spray\n除草 | chúcǎo | to weed\n草 | cǎo | grass; weeds\n採 | cǎi | to pick\n採收 | cǎishōu | to harvest\n籃子 | lánzi | basket\n鋤頭 | chútou | hoe\n鐮刀 | liándāo | sickle\n剪 | jiǎn | to trim; to cut\n樹 | shù | tree\n葉子 | yèzi | leaf\n花 | huā | flower\n香蕉 | xiāngjiāo | banana\n高麗菜 | gāolìcài | cabbage\n番茄 | fānqié | tomato\n草莓 | cǎoméi | strawberry\n雞舍 | jīshè | chicken coop\n雞 | jī | chicken (animal)\n撿 | jiǎn | to pick up; to collect\n牛 | niú | cow\n飼料 | sìliào | animal feed\n曬 | shài | to dry in the sun\n中暑 | zhòngshǔ | heatstroke\n帽子 | màozi | hat\n雨鞋 | yǔxié | rain boots\n蟲 | chóng | insect; worm\n蛇 | shé | snake\n蚊子 | wénzi | mosquito\n推 | tuī | to push\n拉 | lā | to pull\n挖 | wā | to dig\n土 | tǔ | soil\n這些 | zhèxiē | these\n那些 | nàxiē | those\n傍晚 | bàngwǎn | late afternoon; dusk', E'A：阿明，今天我們採高麗菜。 | Āmíng, jīntiān wǒmen cǎi gāolìcài. | Ah-Ming, today we are harvesting cabbage.\nB：好。用這把刀子嗎？ | Hǎo. Yòng zhè bǎ dāozi ma? | Okay. Should I use this knife?\nA：對。採好放籃子裡。 | Duì. Cǎihǎo fàng lánzi lǐ. | Yes. Put them in the basket after cutting.\nB：老闆，那邊的菜有很多蟲。 | Lǎobǎn, nàbiān de cài yǒu hěn duō chóng. | Boss, the vegetables over there have a lot of worms.\nA：明天要噴農藥。你今天先除草。 | Míngtiān yào pēn nóngyào. Nǐ jīntiān xiān chúcǎo. | We will spray pesticide tomorrow. Weed today.\nB：知道了。溫室裡的番茄要澆水嗎？ | Zhīdào le. Wēnshì lǐ de fānqié yào jiāoshuǐ ma? | Got it. Do the tomatoes in the greenhouse need water?\nA：要，下午四點澆。中午太熱，你休息一下。 | Yào, xiàwǔ sì diǎn jiāo. Zhōngwǔ tài rè, nǐ xiūxí yíxià. | Yes, water them at four in the afternoon. It is too hot at noon, so take a rest.\nB：謝謝老闆！ | Xièxie lǎobǎn! | Thank you, boss!', E'農工', E'Farm Work'),
    (17, E'身體不舒服與看醫生', E'Feeling Sick & Seeing a Doctor', 12, E'目標：會說身體哪裡痛、有什麼症狀；會在診所掛號、看懂藥袋上的吃法；會說自己對什麼過敏。句型：我＋身體部位＋痛（我頭痛）、我有一點＋症狀、一天吃幾次？、我對……過敏。發音：「一天三次」唸 yì tiān sān cì；「有一點」唸 yǒu yìdiǎn；「耳朵」的「朵」唸輕聲 ěrduo。台灣讀音：「驗血」台灣口語唸 yànxiě。文化：在台灣看病要帶健保卡，診所看病通常只要付掛號費和部分負擔，不用很貴；藥袋上會寫一天吃幾次、飯前或飯後，看不懂可以請藥師說明；生病請假要跟雇主說，拿醫生開的證明。', E'Goals: say where it hurts and what your symptoms are, register at a clinic, understand the instructions on a medicine bag, and say what you are allergic to. Patterns: 我 (wǒ) + body part + 痛 (tòng) (我頭痛 wǒ tóu tòng), 我有一點 (wǒ yǒu yìdiǎn) + symptom, 一天吃幾次？ (Yì tiān chī jǐ cì?), 我對……過敏 (wǒ duì … guòmǐn). Pronunciation: 一天三次 is yì tiān sān cì; 有一點 is yǒu yìdiǎn; 朵 (duǒ) in 耳朵 (ěrduo) is neutral (ěrduo). Taiwan reading: 驗血 is yànxiě in everyday speech. Culture: bring your NHI card when you see a doctor in Taiwan. At a clinic you usually pay only a small registration fee and co-payment. The medicine bag says how many times a day and whether before or after meals; ask the pharmacist if you do not understand. When you are sick, tell your employer and bring a doctor''s note.', E'我頭痛，也有一點發燒。 | Wǒ tóutòng, yě yǒu yìdiǎn fāshāo. | I have a headache and a slight fever.\n請帶健保卡來掛號。 | Qǐng dài jiànbǎokǎ lái guàhào. | Please bring your NHI card to register.\n這個藥一天三次，飯後吃。 | Zhège yào yì tiān sān cì, fànhòu chī. | Take this medicine three times a day after meals.\n我對海鮮過敏。 | Wǒ duì hǎixiān guòmǐn. | I am allergic to seafood.\n多休息，多喝水。 | Duō xiūxí, duō hē shuǐ. | Get plenty of rest and drink lots of water.', E'醫院 | yīyuàn | hospital\n診所 | zhěnsuǒ | clinic\n醫生 | yīshēng | doctor\n護理師 | hùlǐshī | nurse\n牙醫 | yáyī | dentist\n看醫生 | kàn yīshēng | to see a doctor\n掛號 | guàhào | to register (at a clinic)\n健保卡 | jiànbǎokǎ | NHI card\n藥局 | yàojú | pharmacy\n藥師 | yàoshī | pharmacist\n頭 | tóu | head\n頭痛 | tóutòng | headache\n頭暈 | tóuyūn | dizzy\n肚子 | dùzi | belly\n肚子痛 | dùzi tòng | stomachache\n牙痛 | yátòng | toothache\n喉嚨 | hóulóng | throat\n感冒 | gǎnmào | a cold; to catch a cold\n鼻子 | bízi | nose\n流鼻水 | liú bíshuǐ | runny nose\n眼睛 | yǎnjīng | eyes\n耳朵 | ěrduo | ear\n手 | shǒu | hand\n腳 | jiǎo | foot\n背 | bèi | back (of the body)\n腰 | yāo | lower back; waist\n想吐 | xiǎng tù | to feel like vomiting\n吐 | tù | to vomit\n過敏 | guòmǐn | allergy; allergic\n次 | cì | times (how often)\n顆 | kē | measure word for pills\n睡前 | shuìqián | before bed\n休息 | xiūxí | to rest\n打針 | dǎzhēn | to get an injection\n驗血 | yànxiě | blood test\n住院 | zhùyuàn | to be hospitalized\n嚴重 | yánzhòng | serious\n好多了 | hǎo duō le | much better\n藥水 | yàoshuǐ | liquid medicine\n開藥 | kāiyào | to prescribe medicine\n症狀 | zhèngzhuàng | symptom\n部分負擔 | bùfèn fùdān | co-payment\n掛號費 | guàhàofèi | registration fee\n最好 | zuìhǎo | had better; best', E'A：您好，我要掛號。 | Nín hǎo, wǒ yào guàhào. | Hello, I would like to register.\nB：請給我健保卡。你哪裡不舒服？ | Qǐng gěi wǒ jiànbǎokǎ. Nǐ nǎlǐ bù shūfú? | Please give me your NHI card. What is wrong?\nA：我喉嚨痛，咳嗽，流鼻水。 | Wǒ hóulóng tòng, késòu, liú bíshuǐ. | I have a sore throat, a cough and a runny nose.\nB：有發燒嗎？ | Yǒu fāshāo ma? | Do you have a fever?\nA：昨天晚上三十八度。 | Zuótiān wǎnshàng sānshíbā dù. | It was 38 degrees last night.\nB：你感冒了。我開三天的藥給你。 | Nǐ gǎnmào le. Wǒ kāi sān tiān de yào gěi nǐ. | You have a cold. I will give you three days of medicine.\nA：一天吃幾次？ | Yì tiān chī jǐ cì? | How many times a day do I take it?\nB：一天三次，飯後吃，睡前再吃一包。 | Yì tiān sān cì, fànhòu chī, shuìqián zài chī yì bāo. | Three times a day after meals, and one more pack before bed.\nA：謝謝醫生。我明天可以上班嗎？ | Xièxie yīshēng. Wǒ míngtiān kěyǐ shàngbān ma? | Thank you, doctor. Can I go to work tomorrow?\nB：最好休息一天，多喝水。 | Zuìhǎo xiūxí yì tiān, duō hē shuǐ. | You had better rest for a day and drink lots of water.', E'生活服務', E'Health & Services'),
    (18, E'手機、網路、天氣與聯絡家人', E'Phones, Internet, Weather & Family', 10, E'目標：會借充電、問無線網路密碼；會跟家人視訊、傳訊息；聽懂天氣預報和颱風假的消息。句型：可以＋動作＋嗎？（可以充電嗎？）、……的密碼是什麼？、要下雨了、明天有颱風。發音：「沒電了」唸 méi diàn le；「女兒」要寫 nǚ''ér；「颱風」táifēng 的 f 要上排牙齒輕碰下唇。台灣讀音：「訊息」台灣唸 xùnxí。文化：台灣夏天到秋天常有颱風，政府會宣布「停班停課」，聽新聞或看手機通知；颱風天不要出門，先準備水、食物和手電筒，手機要充好電；在宿舍用網路、打電話要注意時間，不要吵到室友。', E'Goals: ask to charge your phone and for the Wi-Fi password, video call and message your family, and understand weather forecasts and typhoon-day news. Patterns: 可以 (kěyǐ) + action + 嗎？ (ma?) (可以充電嗎？ Kěyǐ chōngdiàn ma?), ……的密碼是什麼？ (… de mìmǎ shì shénme?), 要下雨了 (yào xià yǔ le), 明天有颱風 (míngtiān yǒu táifēng). Pronunciation: 沒電了 is méi diàn le; write nǚ''ér with the apostrophe; for the f in táifēng, touch your top teeth lightly to your lower lip. Taiwan reading: 訊息 is xùnxí. Culture: typhoons often hit Taiwan from summer to autumn, and the government announces 停班停課 (tíngbān tíngkè) (no work, no school), so follow the news and phone alerts. Stay indoors on typhoon days, keep water, food and a flashlight ready, and charge your phone. Mind the time when you use the internet or make calls in the dorm so you do not disturb your roommates.', E'我的手機沒電了，可以充電嗎？ | Wǒ de shǒujī méi diàn le, kěyǐ chōngdiàn ma? | My phone battery is dead. Can I charge it?\n請問無線網路的密碼是什麼？ | Qǐngwèn wúxiàn wǎnglù de mìmǎ shì shénme? | Excuse me, what is the Wi-Fi password?\n晚上我跟家人視訊。 | Wǎnshàng wǒ gēn jiārén shìxùn. | I video call my family in the evening.\n明天有颱風，要停班停課。 | Míngtiān yǒu táifēng, yào tíngbān tíngkè. | A typhoon is coming tomorrow, so work and school are suspended.\n要下雨了，記得帶雨傘。 | Yào xiàyǔ le, jìde dài yǔsǎn. | It is going to rain. Remember to take an umbrella.', E'手機 | shǒujī | cell phone\n充電 | chōngdiàn | to charge (a battery)\n充電器 | chōngdiànqì | charger\n沒電了 | méi diàn le | the battery is dead\n網路 | wǎnglù | internet\n無線網路 | wúxiàn wǎnglù | Wi-Fi\n訊號 | xùnhào | signal\n上網 | shàngwǎng | to go online\n下載 | xiàzài | to download\n打電話 | dǎ diànhuà | to make a phone call\n視訊 | shìxùn | video call\n傳 | chuán | to send (a message)\n訊息 | xùnxí | message\n儲值卡 | chǔzhíkǎ | prepaid card\n門號 | ménhào | mobile number (SIM)\n想家 | xiǎngjiā | homesick\n家 | jiā | home; family\n爸爸 | bàba | dad\n媽媽 | māma | mom\n老公 | lǎogōng | husband\n老婆 | lǎopó | wife\n包裹 | bāoguǒ | parcel\n寄 | jì | to mail\n郵局 | yóujú | post office\n天氣 | tiānqì | weather\n下雨 | xiàyǔ | to rain\n雨傘 | yǔsǎn | umbrella\n颱風 | táifēng | typhoon\n地震 | dìzhèn | earthquake\n晴天 | qíngtiān | sunny day\n陰天 | yīntiān | cloudy day\n風 | fēng | wind\n外套 | wàitào | jacket\n停班停課 | tíngbān tíngkè | no work, no school (typhoon day)\n停電 | tíngdiàn | power outage\n新聞 | xīnwén | news\n記得 | jìde | to remember\n手電筒 | shǒudiàntǒng | flashlight\n可能 | kěnéng | maybe; possibly\n真的 | zhēn de | really\n冬天 | dōngtiān | winter\n夏天 | xiàtiān | summer', E'A：安娜，你看新聞了嗎？明天有颱風。 | Ānnà, nǐ kàn xīnwén le ma? Míngtiān yǒu táifēng. | Anna, have you seen the news? A typhoon is coming tomorrow.\nB：真的嗎？要上班嗎？ | Zhēn de ma? Yào shàngbān ma? | Really? Do we have to work?\nA：台北停班停課，不用上班。 | Táiběi tíngbān tíngkè, búyòng shàngbān. | Work and school are suspended in Taipei, so no work.\nB：太好了！我可以跟我女兒視訊。 | Tài hǎo le! Wǒ kěyǐ gēn wǒ nǚ''ér shìxùn. | Great! I can video call my daughter.\nA：手機要先充電，颱風可能停電。 | Shǒujī yào xiān chōngdiàn, táifēng kěnéng tíngdiàn. | Charge your phone first. The typhoon may cause a power outage.\nB：對。宿舍的網路密碼是多少？ | Duì. Sùshè de wǎnglù mìmǎ shì duōshǎo? | Right. What is the dorm''s internet password?\nA：在冰箱上面，我傳訊息給你。 | Zài bīngxiāng shàngmiàn, wǒ chuán xùnxí gěi nǐ. | It is on the fridge. I will message it to you.\nB：謝謝！颱風天不要出去。 | Xièxie! Táifēngtiān búyào chūqù. | Thanks! Do not go out on the typhoon day.', E'生活服務', E'Health & Services'),
    (19, E'緊急求助與勞工權益', E'Emergencies, Getting Help & Worker Rights', 10, E'目標：會打一一九叫救護車、一一零報警；會說出地址和發生什麼事；知道遇到不公平的事可以打一九五五勞工專線求助。句型：請＋動作（請叫救護車）、我的……被偷了、這裡是＋地址、我要＋申訴／報警。發音：電話號碼一個一個字唸，「一」唸 yī（一一九 yī yī jiǔ）；「不能」唸 bù néng；「拜託」bàituō。文化：在台灣，一一九是火災和救護車，一一零是警察，一九五五是勞動部的勞工諮詢申訴專線，二十四小時免費，有英文等外語服務；馬尼拉經濟文化辦事處（MECO）可以協助菲律賓人；被打、被罵、被扣證件或薪水不對，都可以求助，不用害怕。', E'Goals: call 119 for an ambulance and 110 for the police, give your address and say what happened, and know that you can call the 1955 labor hotline when you are treated unfairly. Patterns: 請 (qǐng) + action (請叫救護車 Qǐng jiào jiùhùchē), 我的……被偷了 (wǒ de … bèi tōu le), 這裡是 (zhèlǐ shì) + address, 我要 (wǒ yào) + 申訴 (shēnsù)／報警 (bàojǐng). Pronunciation: read phone numbers digit by digit, with 一 (yī) as yī (一一九 yī yī jiǔ); 不能 is bù néng; 拜託 is bàituō. Culture: in Taiwan, 119 is for fires and ambulances, 110 is the police, and 1955 is the Ministry of Labor hotline for questions and complaints. It is free, open 24 hours and has English and other languages. The Manila Economic and Cultural Office (MECO) can help Filipinos. If you are hit or shouted at, your documents are taken, or your pay is wrong, you can ask for help; do not be afraid.', E'請叫救護車！ | Qǐng jiào jiùhùchē! | Please call an ambulance!\n我的錢包被偷了，我要報警。 | Wǒ de qiánbāo bèi tōu le, wǒ yào bàojǐng. | My wallet was stolen. I want to report it to the police.\n一九五五有英文服務。 | Yī jiǔ wǔ wǔ yǒu Yīngwén fúwù. | The 1955 hotline has service in English.\n這裡是中山路一百號。 | Zhèlǐ shì Zhōngshān Lù yìbǎi hào. | This is No. 100, Zhongshan Road.\n我很害怕，請幫幫我。 | Wǒ hěn hàipà, qǐng bāngbang wǒ. | I am scared. Please help me.', E'報警 | bàojǐng | to call the police\n警察 | jǐngchá | police officer\n警察局 | jǐngchájú | police station\n救護車 | jiùhùchē | ambulance\n消防車 | xiāofángchē | fire truck\n一一九 | yī yī jiǔ | 119 (fire and ambulance)\n一一零 | yī yī líng | 110 (police)\n一九五五 | yī jiǔ wǔ wǔ | 1955 (labor hotline)\n專線 | zhuānxiàn | hotline\n勞工局 | láogōngjú | labor affairs bureau\n馬尼拉經濟文化辦事處 | Mǎnílā Jīngjì Wénhuà Bànshìchù | MECO (Philippine office in Taiwan)\n緊急 | jǐnjí | emergency; urgent\n狀況 | zhuàngkuàng | situation\n幫助 | bāngzhù | help (noun)\n求助 | qiúzhù | to ask for help\n拜託 | bàituō | please (I beg you)\n生氣 | shēngqì | angry\n打人 | dǎ rén | to hit someone\n罵人 | màrén | to yell at someone\n害怕 | hàipà | afraid\n偷 | tōu | to steal\n小偷 | xiǎotōu | thief\n被 | bèi | (passive marker) was done to\n錢包 | qiánbāo | wallet\n申訴 | shēnsù | to file a complaint\n權益 | quányì | rights\n法律 | fǎlǜ | law\n違法 | wéifǎ | illegal\n公平 | gōngpíng | fair\n不公平 | bù gōngpíng | unfair\n免費 | miǎnfèi | free of charge\n二十四小時 | èrshísì xiǎoshí | 24 hours\n服務 | fúwù | service\n英文 | Yīngwén | English (language)\n中文 | Zhōngwén | Chinese (language)\n地點 | dìdiǎn | location\n路 | lù | road\n樓 | lóu | floor (of a building)\n附近 | fùjìn | nearby\n不能 | bù néng | cannot\n回答 | huídá | to answer\n移動 | yídòng | to move (someone or something)\n意識 | yìshì | consciousness\n說話 | shuōhuà | to talk\n冷靜 | lěngjìng | calm\n電話號碼 | diànhuà hàomǎ | phone number', E'A：一一九，請問有什麼緊急狀況？ | Yī yī jiǔ, qǐngwèn yǒu shénme jǐnjí zhuàngkuàng? | 119, what is your emergency?\nB：我的阿公跌倒了，頭流血了！ | Wǒ de āgōng diédǎo le, tóu liúxiě le! | My grandpa fell and his head is bleeding!\nA：他有意識嗎？會說話嗎？ | Tā yǒu yìshì ma? Huì shuōhuà ma? | Is he conscious? Can he talk?\nB：有，他會說話，可是不能站起來。 | Yǒu, tā huì shuōhuà, kěshì bù néng zhàn qǐlái. | Yes, he can talk, but he cannot stand up.\nA：地址在哪裡？ | Dìzhǐ zài nǎlǐ? | What is the address?\nB：中山路一百號三樓。 | Zhōngshān Lù yìbǎi hào sān lóu. | Third floor, No. 100, Zhongshan Road.\nA：好，救護車馬上到。不要移動他。 | Hǎo, jiùhùchē mǎshàng dào. Búyào yídòng tā. | Okay, the ambulance is on its way. Do not move him.\nB：好，謝謝！拜託快一點！ | Hǎo, xièxie! Bàituō kuài yìdiǎn! | Okay, thank you! Please hurry!', E'生活服務', E'Health & Services'),
    (20, E'總複習與模擬測驗', E'Review & Mock Test', 10, E'目標：複習全部單元最重要的詞彙與句型；完成仿 TOCFL 入門級的聽力與閱讀題；完成口說任務（自我介紹、說上班時間、說明緊急狀況、反映薪水問題）。測驗方式：看標示選意思（危險、禁止吸菸、出口）、聽句子選圖片、看拼音唸句子、兩人角色扮演。拼音重點回顧：三聲連讀照標原調；「不」「一」依後面的聲調變調；輕聲不標；j、q、x、y 後的 ü 寫成 u；a、o、e 開頭的音節前加隔音符號。文化：考試只是開始，在台灣每天多說一點中文，不懂就問「請再說一次」，大家都會願意幫你。', E'Goals: review the key words and patterns from every unit, take TOCFL Novice-style listening and reading questions, and complete speaking tasks (introduce yourself, say your working hours, explain an emergency, raise a pay problem). Test format: match signs to meanings (危險 wéixiǎn, 禁止吸菸 jìnzhǐ xīyān, 出口 chūkǒu), listen and choose the picture, read sentences aloud from pinyin, and role-play in pairs. Pinyin review: two 3rd tones keep their written marks; 不 (bù) and 一 (yī) change with the next tone; the neutral tone has no mark; ü after j, q, x, y is written u; add an apostrophe before a syllable starting with a, o or e. Culture: the test is only the beginning. Speak a little more Chinese every day in Taiwan, and when you do not understand, say 請再說一次 (Qǐng zài shuō yí cì). People will be glad to help.', E'「危險」是什麼意思？ | "Wéixiǎn" shì shénme yìsi? | What does 危險 mean?\n請用中文說：你的名字、國籍和工作。 | Qǐng yòng Zhōngwén shuō: nǐ de míngzi, guójí hàn gōngzuò. | Say your name, nationality and job in Chinese.\n看到「禁止吸菸」，你可以抽菸嗎？ | Kàndào "jìnzhǐ xīyān", nǐ kěyǐ chōuyān ma? | When you see 禁止吸菸, can you smoke?\n阿嬤發燒了，你要跟誰說？ | Āmà fāshāo le, nǐ yào gēn shéi shuō? | Grandma has a fever. Who should you tell?\n垃圾車幾點來？ | Lèsèchē jǐ diǎn lái? | What time does the garbage truck come?', E'你好 | nǐ hǎo | hello\n謝謝 | xièxie | thank you\n對不起 | duìbuqǐ | sorry\n不好意思 | bù hǎoyìsi | excuse me (sorry to bother you)\n請問 | qǐngwèn | excuse me, may I ask\n再見 | zàijiàn | goodbye\n多少 | duōshǎo | how many; how much\n幾點 | jǐ diǎn | what time\n星期 | xīngqí | week\n護照 | hùzhào | passport\n居留證 | jūliúzhèng | residence permit (ARC)\n仲介 | zhòngjiè | broker; recruitment agent\n垃圾 | lèsè | trash\n垃圾車 | lèsèchē | garbage truck\n資源回收 | zīyuán huíshōu | recycling\n便當 | biàndāng | lunch box\n微波 | wéibō | to microwave\n捷運 | jiéyùn | MRT (metro)\n悠遊卡 | Yōuyóukǎ | EasyCard\n哪裡 | nǎlǐ | where\n多少錢 | duōshǎo qián | how much (money)\n匯款 | huìkuǎn | to remit; remittance\n上班 | shàngbān | to go to work\n打卡 | dǎkǎ | to clock in or out\n等一下 | děng yíxià | wait a moment\n聽懂 | tīngdǒng | to understand (what is heard)\n危險 | wéixiǎn | ⚠️ sign: danger\n小心 | xiǎoxīn | be careful\n禁止 | jìnzhǐ | ⚠️ sign: prohibited\n出口 | chūkǒu | ⚠️ sign: exit\n安全帽 | ānquánmào | safety helmet\n加班費 | jiābānfèi | overtime pay\n請假 | qǐngjià | to ask for leave\n吃藥 | chīyào | to take medicine\n翻身 | fānshēn | to turn over (in bed)\n血壓 | xiěyā | blood pressure\n打掃 | dǎsǎo | to clean\n洗衣服 | xǐ yīfú | to do the laundry\n不良品 | bùliángpǐn | defective product\n澆水 | jiāoshuǐ | to water (plants)\n中暑 | zhòngshǔ | heatstroke\n掛號 | guàhào | to register (at a clinic)\n健保卡 | jiànbǎokǎ | NHI card\n過敏 | guòmǐn | allergy; allergic\n充電 | chōngdiàn | to charge (a battery)\n颱風 | táifēng | typhoon\n報警 | bàojǐng | to call the police\n救護車 | jiùhùchē | ambulance\n一九五五 | yī jiǔ wǔ wǔ | 1955 (labor hotline)\n拜託 | bàituō | please (I beg you)', E'A：你好，請自我介紹。 | Nǐ hǎo, qǐng zìwǒ jièshào. | Hello, please introduce yourself.\nB：老師好！我叫安娜，我是菲律賓人，我是看護。 | Lǎoshī hǎo! Wǒ jiào Ānnà, wǒ shì Fēilǜbīnrén, wǒ shì kānhù. | Hello, teacher! My name is Anna. I am Filipino and I am a caregiver.\nA：你每天幾點上班？ | Nǐ měitiān jǐ diǎn shàngbān? | What time do you start work every day?\nB：我早上七點起床，八點上班。 | Wǒ zǎoshàng qī diǎn qǐchuáng, bā diǎn shàngbān. | I get up at seven and start work at eight.\nA：如果阿嬤跌倒了，你要做什麼？ | Rúguǒ āmà diédǎo le, nǐ yào zuò shénme? | If Grandma falls, what will you do?\nB：我先看她有沒有受傷，再打一一九。 | Wǒ xiān kàn tā yǒu méiyǒu shòushāng, zài dǎ yī yī jiǔ. | First I check whether she is hurt, then I call 119.\nA：很好。你的加班費不對，你要怎麼說？ | Hěn hǎo. Nǐ de jiābānfèi bú duì, nǐ yào zěnme shuō? | Very good. If your overtime pay is wrong, what do you say?\nB：老闆，不好意思，我的加班費好像少了。 | Lǎobǎn, bù hǎoyìsi, wǒ de jiābānfèi hǎoxiàng shǎo le. | Boss, excuse me, my overtime pay seems short.\nA：說得很好！ | Shuō de hěn hǎo! | Well said!\nB：謝謝老師！ | Xièxie lǎoshī! | Thank you, teacher!', E'複習', E'Review');

-- 先把要更新的單元改成暫時名稱，避免新名稱和其他位置的舊名稱撞到「同課程名稱不可重複」的限制。
UPDATE hr_tc_course_units u SET name = u.name || ' #' || u.id
FROM a1_units v WHERE u.course_id = :course_id AND u.position = v.position;

WITH changed AS (
  UPDATE hr_tc_course_units u SET name = v.name, name_en = v.name_en, hours = v.hours, topics = v.topics, topics_en = v.topics_en,
    examples = v.examples, vocabulary = v.vocabulary, dialogue = v.dialogue, category = v.category, category_en = v.category_en
  FROM a1_units v WHERE u.course_id = :course_id AND u.position = v.position
  RETURNING u.id
)
SELECT count(*) AS updated FROM changed \gset

WITH inserted AS (
  INSERT INTO hr_tc_course_units(center_id, course_id, position, name, name_en, hours, topics, topics_en, examples, vocabulary, dialogue, category, category_en)
  SELECT :center_id, :course_id, v.position, v.name, v.name_en, v.hours, v.topics, v.topics_en, v.examples, v.vocabulary, v.dialogue, v.category, v.category_en
  FROM a1_units v
  WHERE NOT EXISTS (SELECT 1 FROM hr_tc_course_units u WHERE u.course_id = :course_id AND u.position = v.position)
  ON CONFLICT (course_id, name) DO NOTHING
  RETURNING id
)
SELECT count(*) AS added FROM inserted \gset

COMMIT;
\echo '完成：更新單元數：' :updated '，新增單元數：' :added
